window.GOVAN_DATA = {"subjects": [{"id": "geography", "name": "Geography", "strapline": "Our place. Our planet. Our future.", "intro": "Discover landscapes, communities and the connections that shape our world.", "legacy": true, "atlas": "a", "tile": 0, "colour": "#287055"}, {"id": "care", "name": "Care", "strapline": "People at the heart of learning.", "intro": "Understand development, values and the social influences that shape care.", "legacy": true, "atlas": "a", "tile": 1, "colour": "#247b7b"}, {"id": "art", "name": "Art & Design", "strapline": "Imagine. Experiment. Create.", "intro": "Explore ideas, develop your visual voice and build a creative portfolio.", "legacy": true, "atlas": "a", "tile": 2, "colour": "#ac3977"}, {"id": "modern-studies", "name": "Modern Studies", "strapline": "Question the world around you.", "intro": "Investigate democracy, inequality and international issues using evidence.", "legacy": true, "atlas": "a", "tile": 3, "colour": "#6c4b92"}, {"id": "maths", "name": "Maths", "strapline": "Notice patterns. Explain your thinking. Solve something new.", "intro": "Mathematics helps us make fair comparisons, model change and test whether an answer makes sense. Start with a small problem, show your method and learn from an error. These BGE investigations are suggestions for departmental review; your teacher will confirm the pathway and resources for your class. Mathematics and Applications of Mathematics are distinct qualifications, rather than easier and harder versions of one course.", "legacy": false, "atlas": "a", "tile": 4, "colour": "#275d93"}, {"id": "english", "name": "English", "strapline": "Find your voice. Read closely. Make every word count.", "intro": "English is a place to meet other lives, question persuasive messages and express your own thinking. Reading, writing, listening and talking belong together. Suggested BGE units below can be adapted around texts chosen by the department. Senior Scottish set texts and assessment requirements must follow the current national lists; the examples here are original practice, not prescribed texts.", "legacy": false, "atlas": "a", "tile": 5, "colour": "#9b601c"}, {"id": "spanish", "name": "Spanish", "strapline": "Hola, mundo. Build confidence one conversation at a time.", "intro": "Spanish connects communities across several continents, with many accents and identities. You do not need a perfect accent to communicate thoughtfully. Listen for meaning, try a phrase and improve it. Suggested BGE units are starting points, not confirmed school courses. The national Modern Languages framework applies to Spanish, while your teacher selects relevant texts and contexts.", "legacy": false, "atlas": "a", "tile": 6, "colour": "#b3473a"}, {"id": "french", "name": "French", "strapline": "Bonjour, le monde. Make connections through language.", "intro": "French belongs to diverse communities in Europe, Africa, the Caribbean and beyond. Learn to communicate an idea clearly and listen with curiosity. Suggested BGE units can be adapted around the class’s interests. The national Modern Languages framework applies to French; the department confirms texts, sequence and available pathways.", "legacy": false, "atlas": "a", "tile": 7, "colour": "#346c99"}, {"id": "history", "name": "History", "strapline": "Ask the past a better question.", "intro": "History is an investigation into how people lived, why events happened and how we know. Sources never speak entirely for themselves: historians ask who produced them, what they reveal and what is missing. Suggested BGE enquiries below are not confirmed Govan course choices. Senior national courses require Scottish, British and European/world contexts, with specific options selected by the department.", "legacy": false, "atlas": "a", "tile": 8, "colour": "#90612b"}, {"id": "rme", "name": "RME", "strapline": "Explore beliefs. Think carefully. Listen respectfully.", "intro": "Religious and Moral Education explores religious and non-religious worldviews, values and questions about human life. You are never asked to adopt a belief or disclose personal beliefs. Use evidence, acknowledge diversity within traditions and disagree respectfully with ideas. BGE enquiries below are suggestions. Senior qualifications are called Religious, Moral and Philosophical Studies (RMPS), with departmental choices within national areas.", "legacy": false, "atlas": "a", "tile": 9, "colour": "#72528b"}, {"id": "chemistry", "name": "Chemistry", "strapline": "Small particles. Big possibilities.", "intro": "Explore how particles explain materials, medicines and a changing planet. The BGE projects below are suggested S1–S3 experiences for departmental review. Senior Phase headings describe national courses; the activities are original practice, not assessed coursework. Carry out experiments only when directed by your teacher using school safety procedures.", "legacy": false, "atlas": "a", "tile": 10, "colour": "#167b7f"}, {"id": "physics", "name": "Physics", "strapline": "Understand the forces shaping our world.", "intro": "Use models, measurements and mathematics to explain motion, energy and technology. Suggested BGE projects need departmental review. National course content is separated from optional exploration. All physical investigations require teacher direction and school safety procedures; independent tasks here use supplied data, diagrams or simulations.", "legacy": false, "atlas": "a", "tile": 11, "colour": "#394f92"}, {"id": "biology", "name": "Biology", "strapline": "Explore life, from DNA to ecosystems.", "intro": "Investigate how living systems work and how evidence helps us protect them. BGE units are suggestions for S1–S3, not confirmed Govan courses. Higher Biology and Higher Human Biology are different qualifications. Use simulations and supplied datasets independently; laboratory and fieldwork activities require teacher instructions and school procedures.", "legacy": false, "atlas": "b", "tile": 0, "colour": "#39763b"}, {"id": "esol", "name": "ESOL", "strapline": "Your languages are a strength. Make English another tool.", "intro": "English for Speakers of Other Languages supports learners whose first language is not English. Your existing knowledge and languages matter. Work on a manageable next step in reading, writing, listening or speaking, rather than comparing yourself with someone else. Suggested BGE themes are flexible learning contexts, not a fixed course or a judgement of ability. Your teacher will identify the appropriate qualification level.", "legacy": false, "atlas": "b", "tile": 1, "colour": "#317a85"}, {"id": "graphic-communication", "name": "Graphic Communication", "strapline": "Make ideas clear. Make design matter.", "intro": "Communicate technical information accurately and visual messages convincingly. Suggested BGE projects explore drawing, digital design and responsible communication. They are not confirmed school units. Senior Phase combines technical accuracy with visual impact; software is a tool, not the learning goal. Original practice tasks must not be submitted as live assessed assignments.", "legacy": false, "atlas": "b", "tile": 2, "colour": "#357988"}, {"id": "woodwork", "name": "Woodwork", "strapline": "Measure carefully. Make with purpose.", "intro": "Explore materials, craftsmanship and responsible manufacture. BGE projects are suggestions only. Woodwork learning at home should focus on drawings, material choices and evaluation: tools, machines, finishes and practical making require teacher direction and school workshop safety procedures. National 4 and National 5 Practical Woodworking are genuine routes; there is no Higher Practical Woodworking.", "legacy": false, "atlas": "b", "tile": 3, "colour": "#8d602d"}, {"id": "business", "name": "Business", "strapline": "Turn an idea into a reasoned decision.", "intro": "Business explores how organisations meet needs, use resources and respond to change. A good decision considers customers, workers, finance and wider impacts, rather than profit alone. BGE enterprise challenges below are suggested. Senior qualifications are Business at National 3 and National 4, then Business Management at National 5 and Higher. School availability and class examples need departmental confirmation.", "legacy": false, "atlas": "b", "tile": 4, "colour": "#ab4348"}, {"id": "administration", "name": "Administration", "strapline": "Make information clear. Make work run well.", "intro": "Administration is practical problem solving: organising tasks, communicating accurately and turning information into useful documents. Good administrators think about accessibility, confidentiality and the needs of their audience as well as presentation. Suggested BGE projects use invented information. The senior qualification is Administration and IT; national requirements must be met using the software and procedures confirmed by the department.", "legacy": false, "atlas": "b", "tile": 5, "colour": "#44699a"}, {"id": "home-economics", "name": "Home Economics", "strapline": "Skills for food, wellbeing and everyday life.", "intro": "Explore food choices, preparation, sustainability and product development. Home Economics is an umbrella: Practical Cookery and Health and Food Technology are different qualifications. Suggested BGE projects need departmental review. Follow teacher instructions, allergy arrangements and school food-safety procedures for all practical work; independent hub tasks use menus, labels and planning.", "legacy": false, "atlas": "b", "tile": 6, "colour": "#a85b24"}, {"id": "drama", "name": "Drama", "strapline": "Find your voice. Shape a story.", "intro": "Explore how performance and production choices communicate meaning. Suggested BGE units develop imagination, collaboration and analysis; they are not confirmed school courses. Senior Phase choices include acting and production roles under national requirements. Use fictional scenarios sensitively, respect others’ boundaries and follow teacher guidance on recording, movement, equipment and performance texts.", "legacy": false, "atlas": "b", "tile": 7, "colour": "#824e8a"}, {"id": "music", "name": "Music", "strapline": "Listen closely. Create boldly.", "intro": "Develop your musical voice through performing, composing and listening. Suggested BGE experiences are flexible ideas for departmental review. Music and Music Technology are different qualifications. Practice examples here support learning and must not be presented as completed assessed compositions. Respect copyright, recording consent and comfortable listening levels; follow school guidance for equipment and practical sessions.", "legacy": false, "atlas": "b", "tile": 8, "colour": "#207b78"}, {"id": "physical-education", "name": "Physical Education", "strapline": "Move with purpose. Understand performance.", "intro": "Explore the decisions, relationships and evidence behind performance. Suggested BGE themes are examples, not a prescribed school programme. Practical participation follows teacher guidance, inclusion arrangements and school safety procedures. Independent work here involves analysis and reflection, not unsupervised training plans, fitness testing or exercise regimes.", "legacy": false, "atlas": "b", "tile": 9, "colour": "#476c38"}], "content": {"maths": {"id": "maths", "name": "Maths", "strapline": "Notice patterns. Explain your thinking. Solve something new.", "intro": "Mathematics helps us make fair comparisons, model change and test whether an answer makes sense. Start with a small problem, show your method and learn from an error. These BGE investigations are suggestions for departmental review; your teacher will confirm the pathway and resources for your class. Mathematics and Applications of Mathematics are distinct qualifications, rather than easier and harder versions of one course.", "bge": [{"title": "A fair deal", "question": "Which offer really saves money?", "learn": ["Percentages and fractions", "Unit prices and proportion", "Estimation and rounding"], "task": "Compare 750 g of cereal at £2.70 with 1 kg at £3.80. Calculate both prices per kilogram and explain why the smaller pack is better value here.", "extend": "Design two offers where the biggest discount label hides the higher unit price."}, {"title": "Patterns with a purpose", "question": "Can a rule predict a design?", "learn": ["Sequences and expressions", "Substitution", "Connections between tables and graphs"], "task": "A row of joined squares uses 4, 7, 10 matchsticks. Draw the next two arrangements, write a rule and test it for ten squares.", "extend": "Explain why your rule works using the shared sides, rather than just continuing the sequence."}, {"title": "Data detectives", "question": "Can a graph tell a misleading story?", "learn": ["Averages and spread", "Sampling and bias", "Clear axes and scales"], "task": "Invent ten journey times. Draw a correctly labelled graph, then redraw it with a shortened vertical axis. Explain how its impression changes.", "extend": "Compare mean and median when one journey takes an unusually long time."}, {"title": "Shape our space", "question": "How much material will a design need?", "learn": ["Perimeter and area", "Scale drawings", "Units and accuracy"], "task": "Draw a rectangular community garden to scale. Include a path, calculate planting area and estimate fencing length with a gate.", "extend": "Keep the area constant and explore which rectangle uses the least fencing."}], "senior": [{"level": "National 4", "title": "Mathematics", "areas": ["Expressions and Formulae", "Relationships", "Numeracy", "Added value test"], "explain": "The national course combines algebra, geometry and numeracy. Practice projects here support learning; they do not replace required unit evidence.", "assessment": "Internally assessed units and added value test; your teacher confirms arrangements.", "source": {"title": "Qualifications Scotland: Mathematics", "url": "https://www.sqa.org.uk/sqa/45750.html"}}, {"level": "National 5", "title": "Mathematics", "areas": ["Expressions and Formulae", "Relationships", "Applications"], "explain": "Develop algebraic fluency, geometry, trigonometry and problem solving. Topic order and teaching examples are departmental decisions.", "assessment": "Two question papers, including a non-calculator paper. Use the current specification and official marking instructions.", "source": {"title": "Qualifications Scotland: Mathematics", "url": "https://www.sqa.org.uk/sqa/47419.html"}}, {"level": "Higher", "title": "Mathematics", "areas": ["Expressions and Functions", "Relationships and Calculus", "Applications"], "explain": "Build connections among functions, trigonometry, vectors and calculus. Higher extends mathematical reasoning beyond National 5.", "assessment": "Two question papers, one non-calculator; practise complete working as well as final answers.", "source": {"title": "Qualifications Scotland: Mathematics", "url": "https://www.sqa.org.uk/sqa/47910.html"}}, {"level": "National 3–Higher", "title": "Applications of Mathematics", "areas": ["Finance and numeracy", "Statistics and data", "Geometry, measurement and practical modelling, depending on level"], "explain": "A separate nationally specified pathway. National 3, National 4, National 5 and Higher have different requirements: select the exact level on the official page. Availability at Govan requires confirmation.", "assessment": "National 3/4 use internal assessment; National 5 has two papers; Higher has an exam and project.", "source": {"title": "Qualifications Scotland: Applications of Mathematics", "url": "https://www.sqa.org.uk/sqa/81281.html"}}], "skills": [{"title": "Represent the problem", "explain": "A sketch, table or equation makes relationships visible.", "try": "Draw before calculating a ladder or garden problem.", "check": "Have you labelled known quantities, unknowns and units?"}, {"title": "Show a connected method", "explain": "Each line should follow logically from the previous line.", "try": "Solve 3x + 7 = 22, writing the inverse operation.", "check": "Substitute x = 5 into the original equation."}, {"title": "Estimate and check", "explain": "An estimate catches slips a calculator cannot recognise.", "try": "Estimate 19.8 × 5.1 before calculating.", "check": "An answer near 100 is sensible; 1,009.8 is not."}, {"title": "Explain a conclusion", "explain": "A mathematical answer needs its meaning in context.", "try": "Calculate a mean journey time and describe what it represents.", "check": "State minutes, sensible precision and any limitation of the sample."}], "practice": [{"question": "A £48 jacket is reduced by 25%. What is its sale price?", "hint": "Find 25% of £48, then subtract it.", "answer": "25% is one quarter: £12. The sale price is £36. Multiplying £48 by 0.75 gives the same result.", "extend": "After a further 10% reduction the price is £32.40, not £31.20: explain why."}, {"question": "A taxi model is C = 3 + 1.8d, where d is kilometres. Find the cost for 5 km and explain the 3.", "hint": "Separate the fixed charge from the distance charge.", "answer": "C = 3 + 9 = £12. The £3 is a starting charge even before distance is added.", "extend": "At what distance does the model give £21? Show why d = 10."}, {"question": "Scores are 4, 6, 6, 7, 12. Find the median and mean. Which is more affected if 12 becomes 32?", "hint": "Put the data in order and calculate the total.", "answer": "Median = 6; mean = 35 ÷ 5 = 7. Replacing 12 by 32 leaves the median at 6 but raises the mean to 11.", "extend": "Construct a five-number data set with mean 7 and median 9."}], "resources": [{"title": "NRICH problem-solving collection", "url": "https://nrich.maths.org/", "kind": "Try", "task": "Choose one secondary problem. Save a first attempt and a revised strategy, even if you do not finish."}, {"title": "GeoGebra", "url": "https://www.geogebra.org/", "kind": "Try", "task": "Graph y = 2x + 1 and vary the gradient. Describe exactly what changes."}, {"title": "Desmos graphing calculator", "url": "https://www.desmos.com/calculator", "kind": "Try", "task": "Compare x², x² + 3 and (x − 3)²; predict before drawing."}, {"title": "Qualifications Scotland mathematics resources", "url": "https://www.sqa.org.uk/sqa/47419.html", "kind": "Read", "task": "Find the official course overview and a past-paper question matching your current topic."}, {"title": "National Numeracy", "url": "https://www.nationalnumeracy.org.uk/", "kind": "Read", "task": "Find an everyday numeracy example and explain the maths behind it."}], "ipad": [{"title": "An error worth keeping", "steps": ["Photograph your own worked solution.", "Annotate the first incorrect step and explain its cause.", "Record a corrected method without erasing the original."], "evidence": "A before-and-after page explaining one improvement."}, {"title": "Graph explorer", "steps": ["Enter two related functions in a graphing tool.", "Screenshot and label intercepts and turning points where relevant.", "Record a 45-second explanation linking equation and graph."], "evidence": "A labelled graph with your spoken reasoning."}, {"title": "A measured model", "steps": ["Measure a safe classroom object with permission.", "Create a scale diagram using a drawing app.", "Add calculations and a note about measurement uncertainty."], "evidence": "A diagram with units, scale and checked dimensions."}], "careers": [{"title": "Engineering and construction", "linkToLearning": "Scale, geometry and algebra support design and estimation.", "nextStep": "Compare college engineering courses and construction apprenticeships."}, {"title": "Data and statistics", "linkToLearning": "Interpreting variation helps organisations make evidence-based decisions.", "nextStep": "Explore statistics or data science at university and a digital apprenticeship."}, {"title": "Business and finance", "linkToLearning": "Percentages, forecasts and spreadsheets support everyday decisions.", "nextStep": "Investigate accounting technician routes and college business courses."}, {"title": "Health and community services", "linkToLearning": "Numeracy supports timings, quantities and interpreting evidence.", "nextStep": "Look at a relevant college prospectus and ask which maths qualification is required."}], "parentTip": "Ask “How do you know?” and “Can you show it another way?” Praise a corrected error as evidence of perseverance. Short regular practice is more useful than a long session copying answers.", "vocabulary": [{"en": "number", "ar": "عدد"}, {"en": "fraction", "ar": "كسر"}, {"en": "percentage", "ar": "نسبة مئوية"}, {"en": "equation", "ar": "معادلة"}, {"en": "graph", "ar": "رسم بياني"}, {"en": "angle", "ar": "زاوية"}, {"en": "area", "ar": "مساحة"}, {"en": "average", "ar": "متوسط"}], "sourceNotes": [{"title": "Qualifications Scotland: Mathematics", "url": "https://www.sqa.org.uk/sqa/45750.html"}, {"title": "Qualifications Scotland: Mathematics", "url": "https://www.sqa.org.uk/sqa/47419.html"}, {"title": "Qualifications Scotland: Mathematics", "url": "https://www.sqa.org.uk/sqa/47910.html"}, {"title": "Qualifications Scotland: Applications of Mathematics", "url": "https://www.sqa.org.uk/sqa/81281.html"}, {"title": "Current national assessment overview; check session-specific requirements", "url": "https://www.sqa.org.uk/sqa/104755.html"}], "visual": {"title": "One rule, two representations", "question": "Read y = 2x + 1. What is the y-value when x = 3? Explain how the graph shows the fixed value 1.", "answer": "y = 7. The line crosses the vertical axis at 1 and rises 2 units for each 1 unit along. This connects substitution with gradient and intercept.", "svg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 520 360\" role=\"img\" aria-label=\"One rule, two representations\"><rect width=\"520\" height=\"360\" fill=\"#f2f7f8\"/><path d=\"M70 300H460M100 320V30\" stroke=\"#19354a\" stroke-width=\"2\"/><path d=\"M100 265L400 55\" stroke=\"#275d93\" stroke-width=\"4\"/><g fill=\"#19354a\" font-family=\"Arial\" font-size=\"19\"><text x=\"470\" y=\"306\">x</text><text x=\"88\" y=\"25\">y</text><text x=\"80\" y=\"307\">0</text><text x=\"80\" y=\"272\">1</text><text x=\"390\" y=\"327\">3</text><text x=\"70\" y=\"62\">7</text><text x=\"245\" y=\"70\">y = 2x + 1</text></g><path d=\"M400 300V55H100\" stroke=\"#728c9b\" stroke-dasharray=\"5 5\" fill=\"none\"/><circle cx=\"400\" cy=\"55\" r=\"7\" fill=\"#b71d37\"/></svg>"}}, "english": {"id": "english", "name": "English", "strapline": "Find your voice. Read closely. Make every word count.", "intro": "English is a place to meet other lives, question persuasive messages and express your own thinking. Reading, writing, listening and talking belong together. Suggested BGE units below can be adapted around texts chosen by the department. Senior Scottish set texts and assessment requirements must follow the current national lists; the examples here are original practice, not prescribed texts.", "bge": [{"title": "Govan voices", "question": "Whose stories should a place tell?", "learn": ["Narrative viewpoint", "Sensory detail", "Respectful listening"], "task": "Write a 250-word scene set on an imagined Govan street. Let a small detail reveal how your character feels, rather than stating the emotion.", "extend": "Retell 100 words from another viewpoint and explain how readers’ sympathies change."}, {"title": "Persuasion everywhere", "question": "How do words influence a choice?", "learn": ["Audience and purpose", "Evidence and opinion", "Rhetorical techniques"], "task": "Compare two invented slogans for a school reading campaign. Write a persuasive paragraph using a reason, evidence and a clear call to action.", "extend": "Add a counterargument and respond fairly without mocking the opposing view."}, {"title": "Poetry under the microscope", "question": "How can a few lines carry a big idea?", "learn": ["Imagery and word choice", "Sound and rhythm", "Inference supported by quotation"], "task": "Choose a teacher-approved poem. Annotate three details and explain what each suggests about its speaker or theme.", "extend": "Compare the effect of reading one stanza aloud in two different tones."}, {"title": "From page to performance", "question": "What changes when a text is spoken?", "learn": ["Dialogue and character", "Stage directions", "Collaborative discussion"], "task": "Adapt a short original story into a two-person scene. Add purposeful pauses and perform it privately or in class with permission.", "extend": "Explain which narrative detail you could not transfer directly and how you replaced it."}], "senior": [{"level": "National 3/4", "title": "English", "areas": ["Analysis and Evaluation", "Creation and Production", "National 4 added value"], "explain": "Develop reading, listening, writing and talking through texts selected for learners. National 4 includes the added value assignment; National 3 does not.", "assessment": "Internally assessed course evidence; National 4 includes added value. Ask your teacher which evidence is required.", "source": {"title": "Qualifications Scotland: English", "url": "https://www.sqa.org.uk/sqa/45963.html"}}, {"level": "National 5", "title": "English", "areas": ["Reading for Understanding, Analysis and Evaluation", "Critical reading, including Scottish text", "Portfolio writing", "Spoken language"], "explain": "Learn to explain how a writer creates meaning and produce crafted writing. Your department chooses texts within national requirements.", "assessment": "Question papers, writing portfolio and spoken-language requirement. Use current guidance on permitted support.", "source": {"title": "Qualifications Scotland: English", "url": "https://www.sqa.org.uk/sqa/47410.html"}}, {"level": "Higher", "title": "English", "areas": ["Reading for Understanding, Analysis and Evaluation", "Critical reading", "Portfolio writing", "Spoken language"], "explain": "Analyse increasingly complex ideas and style. The Scottish set-text list applies; choices and teaching order belong to the department.", "assessment": "Current course assessment guidance applies, including changes from session 2026–27. Check the official page rather than relying on older paper timings.", "source": {"title": "Qualifications Scotland: English", "url": "https://www.sqa.org.uk/sqa/45963.html"}}], "skills": [{"title": "Quote with purpose", "explain": "A short precise quotation is more useful than copying a whole paragraph.", "try": "Select the two words that best show an uneasy atmosphere.", "check": "Explain their connotations and link back to the question."}, {"title": "Analyse rather than label", "explain": "Naming a metaphor does not explain its effect.", "try": "Complete: “Comparing the street to a river suggests…”", "check": "Describe the shared quality and the impression created."}, {"title": "Plan an argument", "explain": "Arrange reasons so each paragraph moves the argument forward.", "try": "Write a claim, evidence, explanation and a fair counterpoint.", "check": "Could a reader follow why the evidence supports your conclusion?"}, {"title": "Edit in passes", "explain": "Revise ideas before checking individual commas.", "try": "Check structure first, then sentence clarity, then spelling.", "check": "Read aloud and revise one sentence that sounds awkward."}], "practice": [{"question": "Original sentence: “The last bus sighed into the empty street.” Explain the effect of “sighed”.", "hint": "Think about the human action and the mood it implies.", "answer": "“Sighed” personifies the bus, suggesting tiredness or relief at the end of a long day. This makes the empty street feel quiet and weary. A strong response connects the connotation to the atmosphere.", "extend": "Replace “sighed” with “roared”. Explain how the mood changes."}, {"question": "Original claim: “Everyone knows phones improve learning.” Rewrite it as a more credible argument.", "hint": "Avoid unsupported universal claims; suggest relevant evidence.", "answer": "For example: “Phones can support learning when a teacher sets a clear task, such as photographing stages of a design. Their value depends on how they are used.” This qualifies the claim and gives a concrete example.", "extend": "Write a counterargument about distraction and answer it fairly."}, {"question": "Original opening: “Rain hit the window. Mina checked the clock again. Her bag waited by the door.” What can you infer?", "hint": "Combine details, but separate inference from certainty.", "answer": "Mina may be anxious or impatient about leaving: repeatedly checking the clock suggests waiting. The ready bag supports this. We cannot know where she is going from this extract alone.", "extend": "Write two next sentences that confirm one inference without directly naming her emotion."}], "resources": [{"title": "Scottish Book Trust learning resources", "url": "https://www.scottishbooktrust.com/learning-resources", "kind": "Read", "task": "Choose an age-appropriate author resource and make three questions for a reading group."}, {"title": "Authors Live", "url": "https://www.scottishbooktrust.com/authors-live-on-demand", "kind": "Watch", "task": "Watch an author discuss a writing choice; try that technique in your own paragraph."}, {"title": "Scottish Poetry Library", "url": "https://www.scottishpoetrylibrary.org.uk/", "kind": "Read", "task": "Find a poem, select one striking image and explain its effect."}, {"title": "National Library of Scotland: start research", "url": "https://www.nls.uk/tools-for-research/how-to-begin-your-research/", "kind": "Read", "task": "Identify an original source for a writing topic and record author, title and date."}, {"title": "Royal Shakespeare Company learning", "url": "https://www.rsc.org.uk/learn", "kind": "Watch", "task": "Explore a play resource and compare a performance choice with the written dialogue."}], "ipad": [{"title": "Listen to your writing", "steps": ["Draft a paragraph in your usual writing app.", "Use read-aloud or record yourself reading it.", "Revise unclear sentences and save both versions."], "evidence": "An edited paragraph with a note explaining two choices."}, {"title": "A quotation close-up", "steps": ["Use a teacher-approved digital extract.", "Highlight only the words you will analyse.", "Add a voice note explaining effect, context and theme."], "evidence": "Three precise annotations in your own words."}, {"title": "A purposeful podcast", "steps": ["Plan a two-minute review with a clear recommendation.", "Record without including anyone else’s voice without permission.", "Add a transcript and check names and quotations."], "evidence": "An audio review plus accessible transcript."}], "careers": [{"title": "Journalism and communications", "linkToLearning": "Research, verification and clear writing help audiences understand events.", "nextStep": "Explore college media courses and university journalism pathways."}, {"title": "Law and public service", "linkToLearning": "Careful reading and reasoned argument support fair decisions.", "nextStep": "Compare entry requirements and consider a legal administration apprenticeship."}, {"title": "Publishing and creative work", "linkToLearning": "Editing, storytelling and audience awareness support creative industries.", "nextStep": "Build a small portfolio and investigate college creative-writing or media courses."}, {"title": "Every workplace", "linkToLearning": "Professional messages and active listening matter in hospitality, trades and healthcare.", "nextStep": "Ask someone at work which writing or speaking task they use every day."}], "parentTip": "Let your young person choose some reading for pleasure. Ask about a character’s decision or one memorable phrase; a short conversation can develop understanding without turning every book into a test.", "vocabulary": [{"en": "reading", "ar": "قراءة"}, {"en": "writing", "ar": "كتابة"}, {"en": "evidence", "ar": "دليل"}, {"en": "character", "ar": "شخصية"}, {"en": "poem", "ar": "قصيدة"}, {"en": "argument", "ar": "حجة"}, {"en": "opinion", "ar": "رأي"}, {"en": "meaning", "ar": "معنى"}], "sourceNotes": [{"title": "Qualifications Scotland: English", "url": "https://www.sqa.org.uk/sqa/45963.html"}, {"title": "Qualifications Scotland: English", "url": "https://www.sqa.org.uk/sqa/47410.html"}, {"title": "Qualifications Scotland: English", "url": "https://www.sqa.org.uk/sqa/45963.html"}, {"title": "Current national assessment overview; check session-specific requirements", "url": "https://www.sqa.org.uk/sqa/104755.html"}]}, "spanish": {"id": "spanish", "name": "Spanish", "strapline": "Hola, mundo. Build confidence one conversation at a time.", "intro": "Spanish connects communities across several continents, with many accents and identities. You do not need a perfect accent to communicate thoughtfully. Listen for meaning, try a phrase and improve it. Suggested BGE units are starting points, not confirmed school courses. The national Modern Languages framework applies to Spanish, while your teacher selects relevant texts and contexts.", "bge": [{"title": "Así soy yo", "question": "How can I introduce myself confidently?", "learn": ["Greetings and questions", "Adjective agreement", "Giving reasons for preferences"], "task": "Create a fictional profile: name, age, two interests and a reason. Use “Me gusta…” and “porque…”; do not publish personal information.", "extend": "Ask three follow-up questions rather than reading a memorised monologue."}, {"title": "Mi barrio", "question": "What makes a neighbourhood welcoming?", "learn": ["Places and directions", "Hay and no hay", "Comparisons"], "task": "Design a simple imaginary town map. Give directions from the station to a library and describe one improvement.", "extend": "Compare two neighbourhoods using “más… que” and justify a preference."}, {"title": "Un día diferente", "question": "How do routines shape our day?", "learn": ["Time expressions", "Present-tense verbs", "Sequencing events"], "task": "Write six diary sentences about a fictional school day using “primero”, “después” and “finalmente”.", "extend": "Change two events to a past time frame after checking the appropriate verb forms."}, {"title": "Voces del mundo hispano", "question": "Is one culture enough to describe a language?", "learn": ["Spanish-speaking places", "Respectful cultural comparison", "Listening for key details"], "task": "Investigate a celebration through a museum or cultural organisation. Record where, when and what it means to participants.", "extend": "Compare two accounts and identify diversity within one country."}], "senior": [{"level": "National 3/4", "title": "Spanish — Modern Languages", "areas": ["Understanding Language", "Using Language", "National 4 added value assignment"], "explain": "These national courses develop receptive and productive language skills. National 4 adds an assignment; your teacher selects appropriate topics.", "assessment": "Internal unit assessment; National 4 also requires the added value assignment.", "source": {"title": "Qualifications Scotland: Spanish — Modern Languages", "url": "https://www.sqa.org.uk/sqa/45671.html"}}, {"level": "National 5", "title": "Spanish — Modern Languages", "areas": ["Society", "Learning", "Employability", "Culture", "Reading, listening, writing and talking"], "explain": "The four contexts frame language learning. Suggested cultural investigations here are optional enrichment, not an additional national unit.", "assessment": "Reading and writing paper, listening paper, writing assignment and talking performance. Follow current controlled-assessment rules.", "source": {"title": "Qualifications Scotland: Spanish — Modern Languages", "url": "https://www.sqa.org.uk/sqa/45671.html"}}, {"level": "Higher", "title": "Spanish — Modern Languages", "areas": ["Society", "Learning", "Employability", "Culture", "Extended opinions and reasons"], "explain": "Develop richer language, inference and discussion across the national contexts. Your class’s chosen examples are confirmed by the department.", "assessment": "Reading and directed writing, listening, writing assignment and talking performance. Check current official guidance.", "source": {"title": "Qualifications Scotland: Spanish — Modern Languages", "url": "https://www.sqa.org.uk/sqa/46500.html"}}], "skills": [{"title": "Listen in layers", "explain": "First listen for the topic, then for specific detail.", "try": "Predict three words, listen once without a transcript and write a short gist.", "check": "Replay to confirm details and notice negatives or time expressions."}, {"title": "Build a reusable phrase bank", "explain": "Learn a useful chunk with its meaning and an example.", "try": "Save an opinion, a reason and a contrasting connector.", "check": "Can you adapt the phrase to a new topic without copying a whole answer?"}, {"title": "Read for evidence", "explain": "Look for who, when and why before translating every word.", "try": "Underline the phrase supporting each reading answer.", "check": "Check pronouns, negatives and whether the event is past, present or future."}, {"title": "Speak to communicate", "explain": "A clear message matters more than racing through a script.", "try": "Record 30 seconds, listen and improve one pronunciation or verb.", "check": "Can a listener understand your idea, reason and follow-up question?"}], "practice": [{"question": "Read: “Los sábados trabajo en una tienda. Me gusta hablar con los clientes, pero termino muy cansado.” What does the speaker like, and what is the drawback?", "hint": "“Pero” signals a contrast; “cansado” describes how the person feels.", "answer": "They like speaking with customers, but finish very tired. The shop job is on Saturdays. Avoid translating “clientes” as friends.", "extend": "Write a Spanish reply asking what time the work finishes."}, {"question": "Improve: “Me gusta el fútbol. Es bueno.” Give a more precise reason.", "hint": "Use “porque” and say what you enjoy about it.", "answer": "One possibility is “Me gusta el fútbol porque es emocionante y puedo jugar con mis amigos.” There are many valid answers; check that the reason actually explains your opinion.", "extend": "Add a contrasting opinion about another activity using “sin embargo”."}, {"question": "A café bill lists two juices at €2.50 each and one sandwich at €4.20. Ask for the bill and state the total in Spanish.", "hint": "Two juices cost €5.00; add the sandwich.", "answer": "“La cuenta, por favor. Son nueve euros con veinte.” Total €9.20. A polite request is as important as accurate numbers.", "extend": "Practise ordering without a script, then swap customer and server roles."}], "resources": [{"title": "Instituto Cervantes: Aveteca", "url": "https://cvc.cervantes.es/ensenanza/actividades_ave/aveteca.htm", "kind": "Try", "task": "Choose an A1/A2 activity, attempt it first and note three phrases you could reuse."}, {"title": "Language Transfer: Complete Spanish", "url": "https://www.languagetransfer.org/complete-spanish", "kind": "Listen", "task": "Pause before each learner response. Say your own answer and note one pattern you understood."}, {"title": "Instituto Cervantes", "url": "https://cervantes.org/", "kind": "Read", "task": "Find a cultural event and write a short invitation in Spanish."}, {"title": "RAE dictionary", "url": "https://dle.rae.es/", "kind": "Try", "task": "Check the meaning and grammatical gender of three words; dictionaries support, rather than replace, sentence writing."}, {"title": "National 5 Modern Languages", "url": "https://www.sqa.org.uk/sqa/45671.html", "kind": "Read", "task": "Choose Spanish listening or reading practice at your level and compare your answer with official guidance."}], "ipad": [{"title": "My listening laboratory", "steps": ["Choose a short teacher-approved audio.", "Listen before viewing the transcript and record your understanding.", "Compare with the transcript and colour-code new expressions."], "evidence": "A gist, three checked details and two phrases to reuse."}, {"title": "A conversation that grows", "steps": ["Create a short prompt card without full sentences.", "Record a fictional conversation with permission.", "Repeat after improving one tense and one follow-up question."], "evidence": "Two recordings and a brief reflection on what improved."}, {"title": "A visual phrase journey", "steps": ["Photograph objects or signs where photography is permitted.", "Add accurate target-language captions using a checked dictionary.", "Record yourself explaining a connection between the images."], "evidence": "A small narrated slide deck; no identifiable people or personal addresses."}], "careers": [{"title": "Tourism and hospitality", "linkToLearning": "Listening, welcoming visitors and clarifying requests improve service.", "nextStep": "Explore college travel or hospitality courses and tourism apprenticeships."}, {"title": "International business", "linkToLearning": "Language and cultural awareness support customers and partnerships.", "nextStep": "Compare business-with-languages degrees and work-based business routes."}, {"title": "Translation and communication", "linkToLearning": "Accurate meaning, research and register matter more than word substitution.", "nextStep": "Investigate language degrees and practise editing a short bilingual explanation."}, {"title": "Community and public service", "linkToLearning": "Respectful communication helps schools, health and community organisations.", "nextStep": "Explore college routes and ask how language skills complement another profession."}], "parentTip": "Ask your young person to teach you three useful phrases. Let them replay a short recording and identify one improvement. Encourage a small daily practice habit and curiosity about different communities.", "vocabulary": [{"en": "question", "ar": "سؤال"}, {"en": "answer", "ar": "إجابة"}, {"en": "language", "ar": "لغة"}, {"en": "opinion", "ar": "رأي"}, {"en": "past", "ar": "ماضٍ"}, {"en": "present", "ar": "حاضر"}, {"en": "future", "ar": "مستقبل"}, {"en": "culture", "ar": "ثقافة"}], "sourceNotes": [{"title": "Qualifications Scotland: Spanish — Modern Languages", "url": "https://www.sqa.org.uk/sqa/45671.html"}, {"title": "Qualifications Scotland: Spanish — Modern Languages", "url": "https://www.sqa.org.uk/sqa/45671.html"}, {"title": "Qualifications Scotland: Spanish — Modern Languages", "url": "https://www.sqa.org.uk/sqa/46500.html"}, {"title": "Current national assessment overview; check session-specific requirements", "url": "https://www.sqa.org.uk/sqa/104755.html"}]}, "french": {"id": "french", "name": "French", "strapline": "Bonjour, le monde. Make connections through language.", "intro": "French belongs to diverse communities in Europe, Africa, the Caribbean and beyond. Learn to communicate an idea clearly and listen with curiosity. Suggested BGE units can be adapted around the class’s interests. The national Modern Languages framework applies to French; the department confirms texts, sequence and available pathways.", "bge": [{"title": "Moi et les autres", "question": "How can we find something in common?", "learn": ["Introductions and questions", "Adjective agreement", "Opinions with reasons"], "task": "Make a fictional identity card, then interview a partner about two interests using “Qu’est-ce que tu aimes… ?”.", "extend": "Ask a follow-up question using something your partner said."}, {"title": "Mon quartier idéal", "question": "What would make a place better?", "learn": ["Town vocabulary", "Directions and prepositions", "Comparisons"], "task": "Draw an imaginary neighbourhood. Describe what there is, where it is and one reason to visit.", "extend": "Compare it with another imaginary town using “plus… que”."}, {"title": "À table", "question": "How can language help us make a choice?", "learn": ["Food and quantities", "Polite requests", "Reading menus"], "task": "Create a café menu with prices. Role-play an order, clarify an ingredient and check the total.", "extend": "Write a short review with a specific reason for your recommendation."}, {"title": "La francophonie", "question": "Who uses French, and how?", "learn": ["French-speaking communities", "Listening for gist", "Avoiding stereotypes"], "task": "Choose two French-speaking places. Use a cultural organisation’s resource to compare one aspect of daily life.", "extend": "Explain why one person or celebration cannot represent everyone in a country."}], "senior": [{"level": "National 3/4", "title": "French — Modern Languages", "areas": ["Understanding Language", "Using Language", "National 4 added value assignment"], "explain": "These national courses develop receptive and productive language skills. National 4 adds an assignment; your teacher selects appropriate topics.", "assessment": "Internal unit assessment; National 4 also requires the added value assignment.", "source": {"title": "Qualifications Scotland: French — Modern Languages", "url": "https://www.sqa.org.uk/sqa/45671.html"}}, {"level": "National 5", "title": "French — Modern Languages", "areas": ["Society", "Learning", "Employability", "Culture", "Reading, listening, writing and talking"], "explain": "The four contexts frame language learning. Suggested cultural investigations here are optional enrichment, not an additional national unit.", "assessment": "Reading and writing paper, listening paper, writing assignment and talking performance. Follow current controlled-assessment rules.", "source": {"title": "Qualifications Scotland: French — Modern Languages", "url": "https://www.sqa.org.uk/sqa/45671.html"}}, {"level": "Higher", "title": "French — Modern Languages", "areas": ["Society", "Learning", "Employability", "Culture", "Extended opinions and reasons"], "explain": "Develop richer language, inference and discussion across the national contexts. Your class’s chosen examples are confirmed by the department.", "assessment": "Reading and directed writing, listening, writing assignment and talking performance. Check current official guidance.", "source": {"title": "Qualifications Scotland: French — Modern Languages", "url": "https://www.sqa.org.uk/sqa/46500.html"}}], "skills": [{"title": "Listen in layers", "explain": "First listen for the topic, then for specific detail.", "try": "Predict three words, listen once without a transcript and write a short gist.", "check": "Replay to confirm details and notice negatives or time expressions."}, {"title": "Build a reusable phrase bank", "explain": "Learn a useful chunk with its meaning and an example.", "try": "Save an opinion, a reason and a contrasting connector.", "check": "Can you adapt the phrase to a new topic without copying a whole answer?"}, {"title": "Read for evidence", "explain": "Look for who, when and why before translating every word.", "try": "Underline the phrase supporting each reading answer.", "check": "Check pronouns, negatives and whether the event is past, present or future."}, {"title": "Speak to communicate", "explain": "A clear message matters more than racing through a script.", "try": "Record 30 seconds, listen and improve one pronunciation or verb.", "check": "Can a listener understand your idea, reason and follow-up question?"}], "practice": [{"question": "Read: “J’habite près du collège, donc j’y vais à pied. Quand il pleut, je prends le bus.” How does the speaker usually travel, and when does this change?", "hint": "“À pied” and “quand il pleut” are the key phrases.", "answer": "They usually walk because they live near school; they take the bus when it rains. Include the condition rather than saying they always take the bus.", "extend": "Write a sentence comparing this journey with your own or a fictional journey."}, {"question": "Improve: “J’aime la musique. C’est bien.” Give a specific reason.", "hint": "Use “parce que” and explain an effect or benefit.", "answer": "For example, “J’aime la musique parce que cela m’aide à me détendre.” This gives a clear reason. Other accurate reasons are equally valid.", "extend": "Add a different opinion using “cependant” and check your verb agreement."}, {"question": "What is the difference between “Je joue au foot” and “J’ai joué au foot”?", "hint": "Look for the auxiliary and past participle.", "answer": "The first describes playing football in the present or habitually. The second says “I played/have played football”. “Ai” plus “joué” signals the perfect tense.", "extend": "Write a present, past and future sentence about an activity, with a time phrase in each."}], "resources": [{"title": "TV5MONDE video learning", "url": "https://apprendre.tv5monde.com/fr", "kind": "Watch", "task": "Choose A1 or A2, watch once for gist, then complete the listening activities. Arabic navigation is available on the provider’s site."}, {"title": "RFI: Le français facile", "url": "https://francaisfacile.rfi.fr/fr/", "kind": "Listen", "task": "Choose a short audio with a transcript. Listen first, then highlight five useful phrases in the text."}, {"title": "Institut français UK", "url": "https://www.institut-francais.org.uk/", "kind": "Read", "task": "Find a cultural event and produce a short French invitation with time, place and reason to attend."}, {"title": "TV5MONDE dictionary", "url": "https://langue-francaise.tv5monde.com/", "kind": "Try", "task": "Check a word in context and use it in an original sentence."}, {"title": "National 5 Modern Languages", "url": "https://www.sqa.org.uk/sqa/45671.html", "kind": "Read", "task": "Try French reading or listening practice and explain why each detail earns credit."}], "ipad": [{"title": "My listening laboratory", "steps": ["Choose a short teacher-approved audio.", "Listen before viewing the transcript and record your understanding.", "Compare with the transcript and colour-code new expressions."], "evidence": "A gist, three checked details and two phrases to reuse."}, {"title": "A conversation that grows", "steps": ["Create a short prompt card without full sentences.", "Record a fictional conversation with permission.", "Repeat after improving one tense and one follow-up question."], "evidence": "Two recordings and a brief reflection on what improved."}, {"title": "A visual phrase journey", "steps": ["Photograph objects or signs where photography is permitted.", "Add accurate target-language captions using a checked dictionary.", "Record yourself explaining a connection between the images."], "evidence": "A small narrated slide deck; no identifiable people or personal addresses."}], "careers": [{"title": "Tourism and hospitality", "linkToLearning": "Listening, welcoming visitors and clarifying requests improve service.", "nextStep": "Explore college travel or hospitality courses and tourism apprenticeships."}, {"title": "International business", "linkToLearning": "Language and cultural awareness support customers and partnerships.", "nextStep": "Compare business-with-languages degrees and work-based business routes."}, {"title": "Translation and communication", "linkToLearning": "Accurate meaning, research and register matter more than word substitution.", "nextStep": "Investigate language degrees and practise editing a short bilingual explanation."}, {"title": "Community and public service", "linkToLearning": "Respectful communication helps schools, health and community organisations.", "nextStep": "Explore college routes and ask how language skills complement another profession."}], "parentTip": "Ask your young person to teach you three useful phrases. Let them replay a short recording and identify one improvement. Encourage a small daily practice habit and curiosity about different communities.", "vocabulary": [{"en": "question", "ar": "سؤال"}, {"en": "answer", "ar": "إجابة"}, {"en": "language", "ar": "لغة"}, {"en": "opinion", "ar": "رأي"}, {"en": "past", "ar": "ماضٍ"}, {"en": "present", "ar": "حاضر"}, {"en": "future", "ar": "مستقبل"}, {"en": "culture", "ar": "ثقافة"}], "sourceNotes": [{"title": "Qualifications Scotland: French — Modern Languages", "url": "https://www.sqa.org.uk/sqa/45671.html"}, {"title": "Qualifications Scotland: French — Modern Languages", "url": "https://www.sqa.org.uk/sqa/45671.html"}, {"title": "Qualifications Scotland: French — Modern Languages", "url": "https://www.sqa.org.uk/sqa/46500.html"}, {"title": "Current national assessment overview; check session-specific requirements", "url": "https://www.sqa.org.uk/sqa/104755.html"}]}, "history": {"id": "history", "name": "History", "strapline": "Ask the past a better question.", "intro": "History is an investigation into how people lived, why events happened and how we know. Sources never speak entirely for themselves: historians ask who produced them, what they reveal and what is missing. Suggested BGE enquiries below are not confirmed Govan course choices. Senior national courses require Scottish, British and European/world contexts, with specific options selected by the department.", "bge": [{"title": "Govan: work and change", "question": "How did industry reshape a community?", "learn": ["Chronology and change", "Using photographs and maps", "Work and everyday life"], "task": "Compare a historical image of Govan with a modern view from a trusted collection. List three visible changes and two questions the images cannot answer.", "extend": "Investigate whose experiences might be absent from a celebratory account of industry."}, {"title": "Power and protest", "question": "How do ordinary people change society?", "learn": ["Demands and grievances", "Different methods of protest", "Short- and long-term consequences"], "task": "Choose a teacher-approved campaign for rights. Create a timeline linking a grievance, an action and a response.", "extend": "Compare the importance of individual leadership and wider conditions."}, {"title": "Scotland in a connected world", "question": "What can objects reveal about connections?", "learn": ["Trade and migration", "Provenance of objects", "Perspective and empire"], "task": "Use a museum object to trace a connection between Scotland and another place. Distinguish a supported claim from a question.", "extend": "Consider who made the object, who used it and how it reached the collection."}, {"title": "Conflict and remembrance", "question": "Why do societies remember differently?", "learn": ["Cause and consequence", "Personal testimony", "Memorials and interpretation"], "task": "Compare two teacher-approved memorials or museum accounts. Explain their purpose and intended audience.", "extend": "Suggest an additional perspective that would make an exhibition more representative."}], "senior": [{"level": "National 3/4", "title": "History", "areas": ["Scottish contexts", "British contexts", "European and world contexts", "National 4 added value"], "explain": "Develop knowledge and basic source skills through nationally available options. Your teacher confirms the actual periods taught.", "assessment": "Internal unit assessment; National 4 also includes an added value assignment.", "source": {"title": "Qualifications Scotland: History", "url": "https://www.sqa.org.uk/sqa/45628.html"}}, {"level": "National 5", "title": "History", "areas": ["Scottish context", "British context", "European and world context", "Historical research"], "explain": "Apply contextual knowledge, explain factors and evaluate historical sources. Only study your department’s selected options for assessment preparation.", "assessment": "Question paper and assignment. Use current assignment guidance and the permitted resource sheet.", "source": {"title": "Qualifications Scotland: History", "url": "https://www.sqa.org.uk/sqa/47447.html"}}, {"level": "Higher", "title": "History", "areas": ["Scottish history", "British history", "European and world history", "Independent historical enquiry"], "explain": "Develop analysis, evaluation and supported judgements. The selected national options, rather than every historical topic, form your taught course.", "assessment": "Question papers and assignment. The current official page includes assessment resources and course reports.", "source": {"title": "Qualifications Scotland: History", "url": "https://www.sqa.org.uk/sqa/47923.html"}}], "skills": [{"title": "Interrogate provenance", "explain": "Origin and purpose affect how a source can be used.", "try": "Record author, date, audience and purpose before reading closely.", "check": "Explain what that origin helps us investigate; “biased” alone is not an evaluation."}, {"title": "Corroborate carefully", "explain": "Agreement can strengthen a claim, but sources may depend on each other.", "try": "Compare two accounts of the same event and identify a precise agreement.", "check": "Are they independent, and where do their details differ?"}, {"title": "Explain a causal chain", "explain": "A factor matters because it changes what happens next.", "try": "Use “This led to…” to connect a cause with an outcome.", "check": "Have you explained a mechanism rather than simply listing events?"}, {"title": "Reach a supported judgement", "explain": "A conclusion weighs relevant evidence against a clear question.", "try": "Rank two causes using stated criteria.", "check": "Explain why one carries greater weight, while recognising another contribution."}], "practice": [{"question": "Original practice source: a factory owner writes in a public brochure, “Our workers enjoy excellent conditions.” How useful is it for investigating working conditions?", "hint": "Consider what an owner might know and the purpose of a promotional brochure.", "answer": "It offers the employer’s public account and may reveal the image the company wanted to present. Its promotional purpose may encourage omission of problems. Compare it with inspection records and workers’ accounts; do not simply dismiss it as useless.", "extend": "What extra information about date or audience would help evaluation?"}, {"question": "A fictional town’s employment rises after a railway opens, but a new factory also opens. Does the railway alone explain the increase?", "hint": "Distinguish a sequence from a demonstrated cause.", "answer": "No. The railway could improve access to markets and workers, but factory recruitment may also matter. We need evidence about timing, job types and transport use before judging their relative importance.", "extend": "Write a paragraph explaining one possible link and one limitation."}, {"question": "Two accounts agree that a meeting was crowded. One calls it “inspiring”; the other calls it “disorderly”. Identify agreement and disagreement.", "hint": "Separate an observable detail from an interpretation.", "answer": "They agree on high attendance. They differ in judgement about the meeting’s character. Both could describe the same crowd from different perspectives.", "extend": "Suggest a third source that might test a specific claim, such as a photograph or attendance record."}], "resources": [{"title": "National Museums Scotland schools", "url": "https://www.nms.ac.uk/schools", "kind": "Read", "task": "Choose an object and build a question about its maker, use and journey."}, {"title": "National Library of Scotland: research tools", "url": "https://www.nls.uk/tools-for-research/how-to-begin-your-research/", "kind": "Read", "task": "Find a relevant collection and keep a source log with full references."}, {"title": "Imperial War Museums learning", "url": "https://www.iwm.org.uk/learning", "kind": "Watch", "task": "Choose age-appropriate testimony or a film, identify its perspective and compare it with another source."}, {"title": "UK Parliament learning", "url": "https://learning.parliament.uk/en/", "kind": "Watch", "task": "Explore a history-of-democracy resource and distinguish a law from a campaign for change."}, {"title": "Official History papers and marking instructions", "url": "https://www.sqa.org.uk/pastpapers/findpastpaper.htm?subject=History", "kind": "Try", "task": "Attempt one question from your selected option before consulting marking guidance."}], "ipad": [{"title": "Source investigation board", "steps": ["Save a permitted image with its collection reference.", "Annotate observation, inference and uncertainty in different colours.", "Add a second source to test one inference."], "evidence": "A referenced source board with a revised conclusion."}, {"title": "A timeline with an argument", "steps": ["Choose six events relevant to an enquiry.", "Create a timeline with cause-and-effect links.", "Record a short explanation of the most significant turning point."], "evidence": "A timeline that explains change rather than listing dates."}, {"title": "Museum audio guide", "steps": ["Select a teacher-approved object.", "Write a 90-second script with a claim and supporting evidence.", "Record it and provide a transcript and source list."], "evidence": "An accessible audio guide acknowledging what remains unknown."}], "careers": [{"title": "Museums and heritage", "linkToLearning": "Source interpretation helps explain collections to different audiences.", "nextStep": "Explore college heritage-related courses and museum volunteering information."}, {"title": "Law, journalism and research", "linkToLearning": "Checking evidence and recognising perspective support reliable reporting.", "nextStep": "Compare university courses and journalism apprenticeships where available."}, {"title": "Public service and policy", "linkToLearning": "Understanding change helps explain institutions and choices.", "nextStep": "Explore civil-service apprenticeship and university social-science routes."}, {"title": "Tourism and local enterprise", "linkToLearning": "Historical storytelling can connect visitors with a place.", "nextStep": "Investigate college tourism courses and design a sourced local walking-stop script."}], "parentTip": "Ask “What is the evidence?” when discussing a historical programme or family object. Encourage your young person to keep uncertainty visible; a careful question is often more valuable than a confident guess.", "vocabulary": [{"en": "history", "ar": "تاريخ"}, {"en": "source", "ar": "مصدر"}, {"en": "evidence", "ar": "دليل"}, {"en": "cause", "ar": "سبب"}, {"en": "consequence", "ar": "نتيجة"}, {"en": "change", "ar": "تغيير"}, {"en": "chronology", "ar": "تسلسل زمني"}, {"en": "interpretation", "ar": "تفسير"}], "sourceNotes": [{"title": "Qualifications Scotland: History", "url": "https://www.sqa.org.uk/sqa/45628.html"}, {"title": "Qualifications Scotland: History", "url": "https://www.sqa.org.uk/sqa/47447.html"}, {"title": "Qualifications Scotland: History", "url": "https://www.sqa.org.uk/sqa/47923.html"}, {"title": "Current national assessment overview; check session-specific requirements", "url": "https://www.sqa.org.uk/sqa/104755.html"}]}, "rme": {"id": "rme", "name": "RME", "strapline": "Explore beliefs. Think carefully. Listen respectfully.", "intro": "Religious and Moral Education explores religious and non-religious worldviews, values and questions about human life. You are never asked to adopt a belief or disclose personal beliefs. Use evidence, acknowledge diversity within traditions and disagree respectfully with ideas. BGE enquiries below are suggestions. Senior qualifications are called Religious, Moral and Philosophical Studies (RMPS), with departmental choices within national areas.", "bge": [{"title": "Belonging and belief", "question": "What shapes how people see the world?", "learn": ["Religious and non-religious worldviews", "Identity and community", "Diversity within traditions"], "task": "Create a fictional character with several influences on their worldview. Explain why no single label describes everything about them.", "extend": "Compare two first-person accounts from the same tradition without assuming they represent everyone."}, {"title": "What makes an action right?", "question": "Should we judge intentions or consequences?", "learn": ["Reasons and moral claims", "Consequences and duties", "Respectful disagreement"], "task": "Consider a fictional promise broken to help someone in urgent need. Present a reason for keeping the promise and a reason for breaking it.", "extend": "Explain which principle matters most in your judgement and test it against another situation."}, {"title": "Celebration, story and symbol", "question": "Why can a symbol mean more than it shows?", "learn": ["Meaning and interpretation", "Sources and lived experience", "Respectful comparison"], "task": "Choose a teacher-approved celebration. Explain the meaning of one practice using a reliable source from that community.", "extend": "Find a different account and explain how practice varies."}, {"title": "A fairer community", "question": "What do we owe to one another?", "learn": ["Human dignity", "Rights and responsibilities", "Practical moral decisions"], "task": "Design an inclusive community event. Explain how two decisions support participation and respect.", "extend": "Identify a conflict between two reasonable priorities and propose a justified compromise."}], "senior": [{"level": "National 3/4", "title": "Religious, Moral and Philosophical Studies", "areas": ["World Religion", "Morality and Belief", "Religious and Philosophical Questions", "National 4 added value"], "explain": "Study the selected religion and issues through nationally specified areas. The department confirms options; these are not personal faith tests.", "assessment": "Internal units; National 4 also includes an added value assignment.", "source": {"title": "Qualifications Scotland: Religious, Moral and Philosophical Studies", "url": "https://www.sqa.org.uk/sqa/45772.html"}}, {"level": "National 5", "title": "Religious, Moral and Philosophical Studies", "areas": ["World Religion", "Morality and Belief", "Religious and Philosophical Questions"], "explain": "Explain beliefs, analyse responses and support conclusions. Specific religion and issue options are departmental choices within the specification.", "assessment": "Question paper and assignment. Consult the current course page and assessment instructions.", "source": {"title": "Qualifications Scotland: Religious, Moral and Philosophical Studies", "url": "https://www.sqa.org.uk/sqa/47421.html"}}, {"level": "Higher", "title": "Religious, Moral and Philosophical Studies", "areas": ["World Religion", "Morality and Belief", "Religious and Philosophical Questions"], "explain": "Develop deeper analysis and evaluation of arguments and perspectives. Use accurate examples while acknowledging diversity within worldviews.", "assessment": "Question papers and assignment under current national arrangements; teachers confirm selected options.", "source": {"title": "Qualifications Scotland: Religious, Moral and Philosophical Studies", "url": "https://www.sqa.org.uk/sqa/47911.html"}}], "skills": [{"title": "Describe accurately", "explain": "Explain a view in terms its holder could recognise.", "try": "Summarise a source without adding your judgement.", "check": "Have you avoided “all believers think” when views vary?"}, {"title": "Build an argument", "explain": "A conclusion needs reasons and relevant examples.", "try": "Write a claim, a reason and an example illustrating that reason.", "check": "Does the example actually support the claim?"}, {"title": "Evaluate fairly", "explain": "Consider the strongest version of another view.", "try": "Write an objection and a possible reply.", "check": "Explain whether the reply answers the objection rather than repeating your opinion."}, {"title": "Listen with respect", "explain": "Understanding does not require agreement.", "try": "Paraphrase a partner’s argument before responding.", "check": "Ask if your summary is fair; challenge the idea without judging the person."}], "practice": [{"question": "“Most people in our group support the rule, so the rule must be morally right.” Is that enough?", "hint": "Popularity and moral justification are different kinds of claim.", "answer": "No. Agreement tells us what a group thinks, but a moral defence also needs reasons, such as fairness, wellbeing or rights. A majority can overlook the interests of a minority.", "extend": "Offer one reason for the rule and one possible objection."}, {"question": "A source says one member of a religion volunteers every week. Can we conclude all members do the same?", "hint": "Think about the limits of a single example.", "answer": "No. The source provides evidence about that individual. It may illustrate a belief in service, but frequency and motivation differ among people. Use careful language such as “some members”.", "extend": "What evidence would help investigate a wider pattern?"}, {"question": "A fictional school has funding for either a quiet study space or extra sports equipment. Give a fair argument for each and a justified decision.", "hint": "Identify the needs each choice meets and who might be affected.", "answer": "Study space may support learners without quiet space at home; equipment may support physical wellbeing and participation. Either conclusion can be justified if it weighs need, access and likely benefit. An unsupported preference is weaker.", "extend": "Suggest a compromise and explain what it would fail to solve."}], "resources": [{"title": "Interfaith Scotland: youth and schools", "url": "https://interfaithscotland.org/resources/youth-and-schools", "kind": "Watch", "task": "Use a first-person resource to record one belief, one practice and one question; avoid generalising to everyone."}, {"title": "Understanding Humanism", "url": "https://understandinghumanism.org.uk/", "kind": "Read", "task": "Explain a humanist approach to a moral question using its own educational resources."}, {"title": "United Nations: Universal Declaration of Human Rights", "url": "https://www.un.org/en/about-us/universal-declaration-of-human-rights", "kind": "Read", "task": "Choose an article and explain a practical situation in which it matters."}, {"title": "UK Parliament learning", "url": "https://learning.parliament.uk/en/", "kind": "Watch", "task": "Explore a rights or law resource, then distinguish what is legal from what is morally justified."}, {"title": "Official RMPS resources", "url": "https://www.sqa.org.uk/sqa/45772.html", "kind": "Try", "task": "Select your level and compare a practice response with official marking guidance."}], "ipad": [{"title": "An argument map", "steps": ["Write a clearly worded moral question.", "Map two views with reasons, examples and objections.", "Record a conclusion that weighs the strongest points."], "evidence": "A balanced map and a justified personal conclusion; no disclosure of faith required."}, {"title": "A worldview glossary", "steps": ["Choose eight terms used in class.", "Add a definition, reliable source and example.", "Use audio or a home-language gloss to support understanding."], "evidence": "An accurate glossary that distinguishes description from judgement."}, {"title": "Reflective audio", "steps": ["Choose an idea you reconsidered.", "Record what you first thought and what evidence challenged it.", "Add a transcript and a remaining question."], "evidence": "A short reflection showing open-mindedness and respectful reasoning."}], "careers": [{"title": "Social care and community work", "linkToLearning": "Listening and understanding values support respectful services.", "nextStep": "Explore college social-care courses and work-based routes."}, {"title": "Law and public policy", "linkToLearning": "Ethical reasoning helps weigh competing rights and responsibilities.", "nextStep": "Compare university law or social-science courses and public-service apprenticeships."}, {"title": "Education and youth work", "linkToLearning": "Explaining ideas and supporting dialogue matter in learning.", "nextStep": "Investigate college youth-work routes and teacher-education requirements."}, {"title": "Health and public service", "linkToLearning": "Careful reasoning and respect for different worldviews support communication.", "nextStep": "Explore healthcare college pathways and relevant university programmes."}], "parentTip": "Ask your young person to explain a reason for a view they do not share. Praise fair representation and thoughtful questions. They should never feel required to share private family beliefs to complete a learning task.", "vocabulary": [{"en": "belief", "ar": "اعتقاد"}, {"en": "religion", "ar": "دين"}, {"en": "values", "ar": "قيم"}, {"en": "respect", "ar": "احترام"}, {"en": "reason", "ar": "سبب"}, {"en": "rights", "ar": "حقوق"}, {"en": "responsibility", "ar": "مسؤولية"}, {"en": "ethics", "ar": "أخلاق"}], "sourceNotes": [{"title": "Qualifications Scotland: Religious, Moral and Philosophical Studies", "url": "https://www.sqa.org.uk/sqa/45772.html"}, {"title": "Qualifications Scotland: Religious, Moral and Philosophical Studies", "url": "https://www.sqa.org.uk/sqa/47421.html"}, {"title": "Qualifications Scotland: Religious, Moral and Philosophical Studies", "url": "https://www.sqa.org.uk/sqa/47911.html"}, {"title": "Current national assessment overview; check session-specific requirements", "url": "https://www.sqa.org.uk/sqa/104755.html"}]}, "esol": {"id": "esol", "name": "ESOL", "strapline": "Your languages are a strength. Make English another tool.", "intro": "English for Speakers of Other Languages supports learners whose first language is not English. Your existing knowledge and languages matter. Work on a manageable next step in reading, writing, listening or speaking, rather than comparing yourself with someone else. Suggested BGE themes are flexible learning contexts, not a fixed course or a judgement of ability. Your teacher will identify the appropriate qualification level.", "bge": [{"title": "Finding my way", "question": "How can I ask for information confidently?", "learn": ["School and community vocabulary", "Polite questions", "Clarifying and checking"], "task": "Use a fictional school map. Ask how to reach three places and repeat the directions back to check understanding.", "extend": "Practise “Could you say that more slowly?” and “Do you mean… ?” in a new situation."}, {"title": "Learning across subjects", "question": "How do I explain what I already know?", "learn": ["Subject vocabulary", "Sequencing an explanation", "Using diagrams and examples"], "task": "Choose a familiar science or geography idea. Label a diagram, then explain it in four linked sentences. Use your home language to plan if helpful.", "extend": "Compare a subject word’s everyday meaning and its technical meaning."}, {"title": "Everyday choices", "question": "How do I compare useful information?", "learn": ["Prices and quantities", "Reading notices", "Giving reasons"], "task": "Compare two fictional travel offers. Identify the destination, time, cost and restrictions, then recommend one for a stated traveller.", "extend": "Explain a limitation of your recommendation when information is missing."}, {"title": "My voice, my story", "question": "How can I communicate an experience?", "learn": ["Past time expressions", "Paragraphs and sequence", "Speaking to an audience"], "task": "Write or record a fictional day that went unexpectedly. Include when, where, what changed and how it ended.", "extend": "Revise one part so a listener can follow the sequence without asking for clarification."}], "senior": [{"level": "National 3", "title": "ESOL", "areas": ["Everyday life", "Reading, writing, listening and speaking", "Work or study contexts as specified"], "explain": "Develop straightforward communication for familiar situations. Placement depends on language learning needs, not age alone.", "assessment": "Internal unit assessment. Your teacher confirms the correct units and evidence.", "source": {"title": "Qualifications Scotland: ESOL", "url": "https://www.sqa.org.uk/sqa/48534.html"}}, {"level": "National 4", "title": "ESOL", "areas": ["ESOL for Everyday Life", "ESOL in Context", "Added value assignment"], "explain": "Develop practical language and select information for a purposeful presentation and response to questions. Topic choices are agreed with the assessor.", "assessment": "Internal units and added value assignment, assessed as pass/fail.", "source": {"title": "Qualifications Scotland: ESOL", "url": "https://www.sqa.org.uk/sqa/47404.html"}}, {"level": "National 5", "title": "ESOL", "areas": ["Everyday life", "Work and study", "Reading, writing, listening and speaking"], "explain": "Understand and use English with increasing independence. Classroom topics support the national language skills; they are not all separate compulsory units.", "assessment": "Reading, writing and listening question papers and a speaking performance under current guidance.", "source": {"title": "Qualifications Scotland: ESOL", "url": "https://www.sqa.org.uk/sqa/45680.html"}}, {"level": "Higher", "title": "ESOL", "areas": ["Complex reading and listening", "Purposeful writing", "Speaking and interaction in everyday, work and study settings"], "explain": "Develop more extended understanding and communication. The department must confirm availability and individual suitability.", "assessment": "Use the current Higher course and assessment documents on the official ESOL page.", "source": {"title": "Qualifications Scotland: ESOL", "url": "https://www.sqa.org.uk/sqa/45678.html"}}], "skills": [{"title": "Read in stages", "explain": "Start with the purpose and layout before unknown words.", "try": "Read a notice for its main message, then locate dates and conditions.", "check": "Can you explain what action the reader should take?"}, {"title": "Listen for signposts", "explain": "Words such as “however” and “finally” show relationships.", "try": "Listen once for gist, then again for two specific details.", "check": "Compare your notes with a transcript after your first attempt."}, {"title": "Keep a useful vocabulary record", "explain": "Store a word with its meaning, example and related forms.", "try": "Add “decide”, “decision” and an original sentence.", "check": "Can you use the right form in a fresh sentence?"}, {"title": "Repair communication", "explain": "Asking for clarification is a skilled response.", "try": "Practise asking someone to repeat, rephrase or explain a word.", "check": "Check the meaning back rather than pretending to understand."}], "practice": [{"question": "Read this original notice: “The homework club opens at 3.15 on Tuesdays. Bring your own notes. Places must be booked before noon on Monday.” What must you do before attending?", "hint": "Find the instruction and its deadline.", "answer": "Book a place before noon on Monday and bring your notes. The club itself opens on Tuesday at 3.15; do not confuse the booking deadline with the start time.", "extend": "Write a polite two-sentence booking request using a fictional name."}, {"question": "Improve this message: “Need help work. Tomorrow?” Make it clear and polite.", "hint": "Include who you are asking, what help is needed and a specific request.", "answer": "For example: “Hello, could you help me understand the graph question? Would it be possible to meet at lunchtime tomorrow?” Clear detail helps the reader respond.", "extend": "Write a reply explaining that tomorrow is unavailable and offering another time."}, {"question": "Read: “Although the bus was late, Hana arrived before the lesson began.” Was Hana late for the lesson? Explain.", "hint": "“Although” introduces a contrast between the bus and Hana’s arrival.", "answer": "No. The bus was late, but Hana arrived before the lesson started. The sentence does not tell us exactly how early she arrived.", "extend": "Rewrite the same meaning using “but”, then explain the punctuation change."}], "resources": [{"title": "British Council LearnEnglish Teens", "url": "https://learnenglishteens.britishcouncil.org/", "kind": "Try", "task": "Choose a level-appropriate reading task, attempt the questions and review one error."}, {"title": "British Council Video zone", "url": "https://learnenglishteens.britishcouncil.org/study-break/video-zone", "kind": "Watch", "task": "Predict the topic, watch once for gist, then use captions or transcript to check three details."}, {"title": "British Council general English audio and reading", "url": "https://learnenglish.britishcouncil.org/free-resources/general", "kind": "Listen", "task": "Choose a short audio and note a useful expression you can use tomorrow."}, {"title": "Scottish Book Trust learning resources", "url": "https://www.scottishbooktrust.com/learning-resources", "kind": "Read", "task": "Choose an accessible story resource and retell it with a beginning, change and ending."}, {"title": "Qualifications Scotland ESOL", "url": "https://www.sqa.org.uk/sqa/45678.html", "kind": "Read", "task": "Find the correct level with your teacher and use its official learner examples or papers."}], "ipad": [{"title": "A personal language notebook", "steps": ["Choose five words from today’s learning.", "Add an English definition, home-language gloss and your own example.", "Record pronunciation and revisit the words after a few days."], "evidence": "Five words used accurately in a new explanation."}, {"title": "Listen, notice, improve", "steps": ["Record a short explanation of an imagined event.", "Listen for one unclear phrase and one missing connection.", "Record again and add a transcript."], "evidence": "Two versions and a specific note about improvement."}, {"title": "Read a diagram aloud", "steps": ["Use a teacher-approved subject diagram.", "Label key terms and organise your explanation in numbered steps.", "Record while pointing to the relevant parts on screen."], "evidence": "A narrated diagram showing subject knowledge and developing English."}], "careers": [{"title": "College and further study", "linkToLearning": "English supports understanding instructions and sharing subject expertise.", "nextStep": "Explore college ESOL and vocational pathways with guidance staff."}, {"title": "Customer service and hospitality", "linkToLearning": "Clarifying requests and speaking politely support visitors and colleagues.", "nextStep": "Compare college hospitality courses and apprenticeships."}, {"title": "Health and community roles", "linkToLearning": "Accurate listening and checking meaning matter in services.", "nextStep": "Investigate relevant college entry requirements and language support."}, {"title": "Your specialist interests", "linkToLearning": "ESOL can support engineering, creative work, business or university study.", "nextStep": "Choose an interest and identify the English tasks used in that field."}], "parentTip": "Continue rich conversations and reading in your home language. Ask your young person to explain one new idea in whichever language helps them think, then practise a short English explanation. Progress in English takes time and does not measure intelligence.", "vocabulary": [{"en": "listen", "ar": "استمع"}, {"en": "speak", "ar": "تحدث"}, {"en": "read", "ar": "اقرأ"}, {"en": "write", "ar": "اكتب"}, {"en": "explain", "ar": "اشرح"}, {"en": "compare", "ar": "قارن"}, {"en": "question", "ar": "سؤال"}, {"en": "example", "ar": "مثال"}], "sourceNotes": [{"title": "Qualifications Scotland: ESOL", "url": "https://www.sqa.org.uk/sqa/48534.html"}, {"title": "Qualifications Scotland: ESOL", "url": "https://www.sqa.org.uk/sqa/47404.html"}, {"title": "Qualifications Scotland: ESOL", "url": "https://www.sqa.org.uk/sqa/45680.html"}, {"title": "Qualifications Scotland: ESOL", "url": "https://www.sqa.org.uk/sqa/45678.html"}, {"title": "Current national assessment overview; check session-specific requirements", "url": "https://www.sqa.org.uk/sqa/104755.html"}]}, "business": {"id": "business", "name": "Business", "strapline": "Turn an idea into a reasoned decision.", "intro": "Business explores how organisations meet needs, use resources and respond to change. A good decision considers customers, workers, finance and wider impacts, rather than profit alone. BGE enterprise challenges below are suggested. Senior qualifications are Business at National 3 and National 4, then Business Management at National 5 and Higher. School availability and class examples need departmental confirmation.", "bge": [{"title": "An idea for Govan", "question": "What need could an enterprise meet?", "learn": ["Needs and wants", "Customers and stakeholders", "Social enterprise"], "task": "Design a fictional service that meets a local need. Identify its customer, benefit, required resources and one possible risk.", "extend": "Explain how a social aim could influence a decision even if it reduces profit."}, {"title": "Know your customer", "question": "How can research improve a decision?", "learn": ["Primary and secondary research", "Sampling", "Question design"], "task": "Write four neutral questions for a fictional reusable-bottle business. Explain who you would ask and why. Do not collect personal data.", "extend": "Identify how a small or unrepresentative sample could mislead the business."}, {"title": "Money that makes sense", "question": "Can a busy business still lose money?", "learn": ["Revenue and costs", "Profit", "Cash flow"], "task": "A fictional stall sells 40 items at £3. Costs total £95. Calculate revenue and profit, then explain why profit is not the same as cash in the bank.", "extend": "Add a delayed customer payment and predict the effect on cash availability."}, {"title": "People and responsible choices", "question": "What makes an organisation work well?", "learn": ["Roles and teamwork", "Motivation", "Environmental and ethical choices"], "task": "Compare two fictional suppliers on cost, reliability and packaging. Recommend one using more than one criterion.", "extend": "Explain a disadvantage of your chosen supplier and how the business could manage it."}], "senior": [{"level": "National 3/4", "title": "Business", "areas": ["Business in Action", "Influences on Business", "National 4 added value assignment"], "explain": "Develop understanding of enterprise, organisations and influences. These are Business courses, not National 5 Business Management under another name.", "assessment": "Internal unit assessment; National 4 includes added value. Check exact course requirements with the teacher.", "source": {"title": "Qualifications Scotland: Business", "url": "https://www.sqa.org.uk/sqa/45945.html"}}, {"level": "National 5", "title": "Business Management", "areas": ["Understanding business", "Management of marketing", "Management of operations", "Management of people", "Management of finance"], "explain": "National content covers organisations and functional areas. Case studies and enterprise activities are teaching choices.", "assessment": "Exam and assignment. Assessment was updated from session 2026–27; use current official documents rather than old weightings.", "source": {"title": "Qualifications Scotland: Business Management", "url": "https://www.sqa.org.uk/sqa/45936.html"}}, {"level": "Higher", "title": "Business Management", "areas": ["Understanding business", "Management of marketing", "Management of operations", "Management of people", "Management of finance"], "explain": "Analyse relationships among business functions and justify decisions using context. Departmental case studies can be gradually added.", "assessment": "Exam and assignment under updated 2026–27 arrangements. Teachers confirm current requirements.", "source": {"title": "Qualifications Scotland: Business Management", "url": "https://www.sqa.org.uk/sqa/45936.html"}}], "skills": [{"title": "Apply to the case", "explain": "A general point becomes useful when linked to the organisation.", "try": "Explain how late deliveries could affect a café specifically.", "check": "Have you connected the delay to stock, service and customer satisfaction?"}, {"title": "Calculate and interpret", "explain": "Numbers need labels and meaning.", "try": "Calculate profit from sales revenue minus total costs.", "check": "State pounds, show working and explain whether the result is a profit or loss."}, {"title": "Analyse a chain", "explain": "Explain how an action produces an outcome.", "try": "Link training to fewer errors and improved customer service.", "check": "Use “because” and “therefore”; avoid just listing advantages."}, {"title": "Make a balanced recommendation", "explain": "A decision has benefits, costs and uncertainty.", "try": "Recommend a supplier using price and reliability evidence.", "check": "Acknowledge a drawback and explain why your preferred factor matters more."}], "practice": [{"question": "A fictional enterprise sells 120 cards at £2.50. Total costs are £220. Calculate revenue and profit.", "hint": "Revenue is price × quantity; profit subtracts costs.", "answer": "Revenue = £300. Profit = £80. £300 is not profit because the business must cover £220 of costs.", "extend": "If sales fall to 80 cards while costs stay £220, the business makes a £20 loss."}, {"question": "A survey asks, “Would you buy our brilliant, affordable lunch?” Identify a weakness and improve it.", "hint": "Look for language that pushes people towards an answer.", "answer": "“Brilliant” and “affordable” are leading descriptions. A more neutral question is “How likely are you to buy this lunch at £4?” with balanced response options.", "extend": "Explain why surveying only friends could still limit the findings."}, {"question": "Supplier A costs less but sometimes delivers late. Supplier B costs more and is reliable. Recommend one for a café with little storage.", "hint": "Consider the consequence of having no stock available.", "answer": "B may be preferable because reliable deliveries reduce the risk of missing ingredients and lost sales when storage is limited. The higher price could reduce margin, so the café should compare that cost with disruption. A justified A recommendation is possible with a credible backup plan.", "extend": "Identify one piece of information needed before a final decision."}], "resources": [{"title": "Business Gateway resource library", "url": "https://www.bgateway.com/resources", "kind": "Read", "task": "Choose a market-research or business-planning guide and apply one idea to your fictional enterprise."}, {"title": "Bank of England education", "url": "https://www.bankofengland.co.uk/education/education-resources", "kind": "Watch", "task": "Explore an explanation of inflation and describe one possible effect on a small business."}, {"title": "Young Enterprise Scotland", "url": "https://www.young-enterprise.org.uk/young-enterprise-scotland", "kind": "Read", "task": "Explore an enterprise programme and identify teamwork or problem-solving skills it develops."}, {"title": "Office for National Statistics", "url": "https://www.ons.gov.uk/", "kind": "Try", "task": "Find a business-related chart. Record its date, units, trend and one limitation."}, {"title": "Official Business Management resources", "url": "https://www.sqa.org.uk/sqa/45936.html", "kind": "Try", "task": "Choose a current case-study question and practise linking every point to the case."}], "ipad": [{"title": "A working financial model", "steps": ["Create a spreadsheet for a fictional product.", "Use formulas for revenue, cost and profit.", "Change the sales quantity and explain what changes."], "evidence": "A labelled spreadsheet with formulas and a short interpretation."}, {"title": "A two-minute pitch", "steps": ["Define a customer problem and your proposed benefit.", "Create three slides with evidence, costs and risks.", "Record a pitch and revise a vague claim."], "evidence": "A concise pitch with a realistic limitation."}, {"title": "Research without collecting identities", "steps": ["Create a mock survey using sample responses.", "Chart the results and label sample size.", "Explain a sampling limitation in a voice note."], "evidence": "An ethical research example using invented data only."}], "careers": [{"title": "Business administration apprenticeships", "linkToLearning": "Organisation and communication support every business function.", "nextStep": "Explore local apprenticeship opportunities and required qualifications."}, {"title": "Marketing and creative enterprise", "linkToLearning": "Research and persuasive communication help reach customers.", "nextStep": "Compare college marketing courses and creative business routes."}, {"title": "Accounting and finance", "linkToLearning": "Accurate calculations and interpretation support decisions.", "nextStep": "Investigate accounting technician study, college and university pathways."}, {"title": "University and entrepreneurship", "linkToLearning": "Business knowledge can combine with another subject or a social aim.", "nextStep": "Read business degree information and compare it with a practical college route."}], "parentTip": "Discuss an everyday business decision such as packaging, opening hours or a price change. Ask who benefits, who might lose out and what evidence would help. Use fictional budgets rather than private family financial details.", "vocabulary": [{"en": "business", "ar": "أعمال تجارية"}, {"en": "customer", "ar": "عميل"}, {"en": "cost", "ar": "تكلفة"}, {"en": "profit", "ar": "ربح"}, {"en": "revenue", "ar": "إيرادات"}, {"en": "market", "ar": "سوق"}, {"en": "employee", "ar": "موظف"}, {"en": "decision", "ar": "قرار"}], "sourceNotes": [{"title": "Qualifications Scotland: Business", "url": "https://www.sqa.org.uk/sqa/45945.html"}, {"title": "Qualifications Scotland: Business Management", "url": "https://www.sqa.org.uk/sqa/45936.html"}, {"title": "Qualifications Scotland: Business Management", "url": "https://www.sqa.org.uk/sqa/45936.html"}, {"title": "Current national assessment overview; check session-specific requirements", "url": "https://www.sqa.org.uk/sqa/104755.html"}]}, "administration": {"id": "administration", "name": "Administration", "strapline": "Make information clear. Make work run well.", "intro": "Administration is practical problem solving: organising tasks, communicating accurately and turning information into useful documents. Good administrators think about accessibility, confidentiality and the needs of their audience as well as presentation. Suggested BGE projects use invented information. The senior qualification is Administration and IT; national requirements must be met using the software and procedures confirmed by the department.", "bge": [{"title": "Run an event", "question": "What needs to happen before the doors open?", "learn": ["Task planning and priorities", "Roles and deadlines", "Clear event information"], "task": "Plan a fictional school exhibition. Create a checklist, schedule and invitation using invented names and dates.", "extend": "Identify a task that depends on another task and explain the effect of delay."}, {"title": "Spreadsheet detectives", "question": "How can a formula reduce repeated work?", "learn": ["Cell references and formulas", "Formatting data", "Checking totals"], "task": "Build a fictional stationery budget with quantity, unit cost and total cost. Use formulas, then change a quantity and check the result.", "extend": "Create a chart only if it helps answer a specific question."}, {"title": "A message that works", "question": "How do I make information easy to act on?", "learn": ["Audience and tone", "Email structure", "Accessible document design"], "task": "Rewrite a confusing fictional event message with a clear subject, required action and deadline.", "extend": "Test whether a reader can find the key action within ten seconds."}, {"title": "Organise responsibly", "question": "Why does a small data error matter?", "learn": ["Accuracy and verification", "File organisation", "Confidentiality"], "task": "Create an invented contact list and spot duplicated or inconsistent entries. Design a sensible folder structure for the project.", "extend": "Explain why a public website should not be used to store pupils’ private information."}], "senior": [{"level": "National 3", "title": "Administration and IT", "areas": ["Administration in Action", "Communication in Administration", "IT Solutions for Administrators"], "explain": "Develop practical administrative and IT skills in straightforward contexts. Classroom software examples are teaching choices.", "assessment": "Three internally assessed units, with course results recorded as pass/fail.", "source": {"title": "Qualifications Scotland: Administration and IT", "url": "https://www.sqa.org.uk/sqa/45943.html"}}, {"level": "National 4", "title": "Administration and IT", "areas": ["Administrative Practices", "IT Solutions for Administrators", "Communication in Administration", "Added value assignment"], "explain": "Apply administration and IT skills to purposeful tasks. A polished practice project does not replace required assessed evidence.", "assessment": "Internal units and added value assignment, assessed as pass/fail.", "source": {"title": "Qualifications Scotland: Administration and IT", "url": "https://www.sqa.org.uk/sqa/45943.html"}}, {"level": "National 5", "title": "Administration and IT", "areas": ["Administrative practices", "IT solutions", "Communication and organisation"], "explain": "Use IT applications accurately and understand administration in the workplace. Tasks and software must match the current specification.", "assessment": "Question paper and assignment; teachers provide authorised assessment materials and explain permitted support.", "source": {"title": "Qualifications Scotland: Administration and IT", "url": "https://www.sqa.org.uk/sqa/45943.html"}}, {"level": "Higher", "title": "Administration and IT", "areas": ["Administrative theory and practice", "Advanced IT application", "Information management and communication"], "explain": "Develop more complex administrative problem solving and efficient IT use. School software access and workflow must be confirmed.", "assessment": "Question paper and assignment under current national conditions. Use current official instructions.", "source": {"title": "Qualifications Scotland: Administration and IT", "url": "https://www.sqa.org.uk/sqa/45943.html"}}], "skills": [{"title": "Read the instruction precisely", "explain": "Action words and conditions determine what a task requires.", "try": "Highlight the file type, audience, deadline and required output.", "check": "Have you completed every part rather than only making the page attractive?"}, {"title": "Check formulas independently", "explain": "A spreadsheet can calculate the wrong thing very efficiently.", "try": "Calculate one row manually and compare it with the formula.", "check": "Check references, ranges, units and what happens when an input changes."}, {"title": "Communicate for action", "explain": "Readers should know what to do next.", "try": "Draft an email with a descriptive subject, brief context and clear request.", "check": "Check recipient, tone, spelling and attachment before sending a practice copy."}, {"title": "Manage versions and information", "explain": "A clear naming system reduces lost work and confusion.", "try": "Save a dated draft and a clearly named final version.", "check": "Can another person identify the correct file without opening every document?"}], "practice": [{"question": "In a spreadsheet, B2 is quantity 6 and C2 is unit price £2.40. What formula belongs in D2, and what is the result?", "hint": "Multiply the two cells rather than typing a fixed total.", "answer": "=B2*C2 gives £14.40. A formula updates when an input changes; a typed 14.40 does not. Apply currency formatting to the output.", "extend": "If the formula is copied down, explain why relative references normally change to B3 and C3."}, {"question": "Original message: “Meeting changed. Come later. Bring it.” Rewrite it so an invented recipient can act on it.", "hint": "Supply the missing time, place, purpose and object.", "answer": "For example: “Project meeting moved to 2 pm on Thursday in Room 4. Please bring the draft exhibition budget.” This replaces vague references with specific information.", "extend": "Add a clear subject line and a request to confirm receipt."}, {"question": "A practice contact list contains two entries for the same fictional person with different phone numbers. Should you delete one immediately?", "hint": "Consider accuracy and the source of the information.", "answer": "No. Flag the inconsistency and verify against the authorised source or agreed procedure before changing it. Guessing could remove the correct record. Use invented data for this exercise.", "extend": "Write a short checking procedure that records who verified the correction and when."}], "resources": [{"title": "Microsoft 365 support", "url": "https://www.microsoft.com/en-gb/microsoft-365/support", "kind": "Watch", "task": "Find help for one spreadsheet or document feature, practise it and explain when it is useful."}, {"title": "Microsoft Learn: Microsoft 365", "url": "https://learn.microsoft.com/en-gb/training/browse/?products=m365", "kind": "Try", "task": "Choose a relevant beginner learning item with your teacher; record one technique you can apply."}, {"title": "ICO: data security advice", "url": "https://ico.org.uk/for-organisations/advice-for-small-organisations/information-security/data-security-advice/", "kind": "Read", "task": "Identify two ways an administrative mistake can expose information. Apply school procedures rather than collecting real personal data."}, {"title": "Business Gateway resources", "url": "https://www.bgateway.com/resources", "kind": "Read", "task": "Choose an organisation or planning guide and turn one section into a practical checklist."}, {"title": "Qualifications Scotland Administration and IT", "url": "https://www.sqa.org.uk/sqa/45943.html", "kind": "Try", "task": "Select your level and compare a practice output with official assessment examples where available."}], "ipad": [{"title": "A portable event organiser", "steps": ["Create a fictional event checklist and calendar plan.", "Draft an accessible invitation with clear headings.", "Export a PDF and check its layout on the iPad screen."], "evidence": "A small event pack with consistent dates and a checked export."}, {"title": "A spreadsheet that explains itself", "steps": ["Enter invented stock or budget data in a spreadsheet.", "Use formulas and descriptive column headings.", "Add a short screen recording explaining one calculation."], "evidence": "A working sheet and narration, with no private records."}, {"title": "An accessibility quality check", "steps": ["Open a practice document on your iPad.", "Check text size, contrast, reading order and image descriptions.", "Revise two barriers and explain the improvement."], "evidence": "A before-and-after document with an accessibility checklist."}], "careers": [{"title": "Business administration apprenticeship", "linkToLearning": "Reliable organisation and communication support teams.", "nextStep": "Explore administration apprenticeships and compare entry requirements."}, {"title": "College Administration and IT", "linkToLearning": "Practical software skills can develop into advanced workplace competence.", "nextStep": "Compare college NC and HNC/HND routes and progression agreements."}, {"title": "Events, hospitality and public services", "linkToLearning": "Scheduling, accurate information and customer care keep services running.", "nextStep": "Investigate event-management or service-sector courses and work-based routes."}, {"title": "University and specialist administration", "linkToLearning": "Information management complements business, health and professional services.", "nextStep": "Compare business or information-related degrees and relevant college articulation routes."}], "parentTip": "Ask your young person to explain the purpose of a document and demonstrate one formula. Encourage a final accuracy check before they finish. Use fictional details for practice instead of family contact lists or financial records.", "vocabulary": [{"en": "document", "ar": "مستند"}, {"en": "spreadsheet", "ar": "جدول بيانات"}, {"en": "formula", "ar": "صيغة"}, {"en": "file", "ar": "ملف"}, {"en": "folder", "ar": "مجلد"}, {"en": "accuracy", "ar": "دقة"}, {"en": "communication", "ar": "تواصل"}, {"en": "deadline", "ar": "موعد نهائي"}], "sourceNotes": [{"title": "Qualifications Scotland: Administration and IT", "url": "https://www.sqa.org.uk/sqa/45943.html"}, {"title": "Qualifications Scotland: Administration and IT", "url": "https://www.sqa.org.uk/sqa/45943.html"}, {"title": "Qualifications Scotland: Administration and IT", "url": "https://www.sqa.org.uk/sqa/45943.html"}, {"title": "Qualifications Scotland: Administration and IT", "url": "https://www.sqa.org.uk/sqa/45943.html"}, {"title": "Current national assessment overview; check session-specific requirements", "url": "https://www.sqa.org.uk/sqa/104755.html"}]}, "chemistry": {"id": "chemistry", "name": "Chemistry", "strapline": "Small particles. Big possibilities.", "intro": "Explore how particles explain materials, medicines and a changing planet. The BGE projects below are suggested S1–S3 experiences for departmental review. Senior Phase headings describe national courses; the activities are original practice, not assessed coursework. Carry out experiments only when directed by your teacher using school safety procedures.", "bge": [{"title": "Kitchen chemistry", "question": "Why does food change when it cooks?", "learn": ["Identify physical and chemical changes.", "Use particle ideas to describe dissolving.", "Separate observations from explanations."], "task": "Annotate three changes in a teacher-provided cooking video. Explain which evidence suggests a new substance formed.", "extend": "Explain why melting chocolate is different from burning toast."}, {"title": "Materials for a better world", "question": "What makes a material suitable?", "learn": ["Compare metals, polymers and ceramics.", "Link properties to uses.", "Consider reuse and recycling."], "task": "Design packaging for a fragile object. Compare two materials using strength, mass and end-of-life evidence.", "extend": "Challenge the claim that every biodegradable material is automatically sustainable."}, {"title": "Acids and alkalis", "question": "How can we describe acidity?", "learn": ["Interpret the pH scale.", "Recognise neutralisation.", "Read hazard information."], "task": "Use a teacher-selected simulation to arrange five solutions by pH and predict changes when acid is neutralised.", "extend": "Explain why pH alone does not tell you every hazard."}, {"title": "Chemistry and our environment", "question": "How can chemistry reduce pollution?", "learn": ["Distinguish elements and compounds.", "Read emissions graphs.", "Evaluate evidence about fuels."], "task": "Compare two published fuel data tables. Write a recommendation with a benefit, limitation and supporting figure.", "extend": "Research how green hydrogen is produced and identify the source of its energy."}], "senior": [{"level": "National 3 / National 4", "title": "Chemistry", "areas": ["Chemical Changes and Structure", "Nature’s Chemistry", "Chemistry in Society"], "explain": "Build chemical knowledge through practical enquiry. National 4 also includes an added-value assignment. Availability depends on school provision.", "assessment": "Internally assessed units; National 4 includes added value. These courses are pass/fail.", "source": {"title": "Qualifications Scotland — Chemistry", "url": "https://www.sqa.org.uk/sqa/45720.html"}}, {"level": "National 5", "title": "National 5 Chemistry", "areas": ["Chemical Changes and Structure", "Nature’s Chemistry", "Chemistry in Society"], "explain": "Study bonding, reaction rates, quantitative chemistry, carbon compounds, energy, metals and the chemical industry within the specification.", "assessment": "Question paper and assignment under the current national assessment requirements. Practise independently; complete assessed work under teacher conditions.", "source": {"title": "Qualifications Scotland — National 5 Chemistry", "url": "https://www.sqa.org.uk/sqa/45722.html"}}, {"level": "Higher", "title": "Higher Chemistry", "areas": ["Chemical Changes and Structure", "Nature’s Chemistry", "Chemistry in Society", "Researching Chemistry skills"], "explain": "Deepen understanding of periodicity, bonding, organic chemistry, equilibria, energy and chemical analysis. Researching Chemistry develops enquiry skills across content.", "assessment": "Question paper and assignment; consult the current specification and teacher guidance for this session.", "source": {"title": "Qualifications Scotland — Higher Chemistry", "url": "https://www.sqa.org.uk/sqa/46504.html"}}], "skills": [{"title": "Plan a fair comparison", "explain": "Change one independent variable and measure a clearly defined outcome. Control other influential variables.", "try": "Plan a simulation comparing reaction rate at three temperatures, with repeats.", "check": "Have you stated what stays constant and how rate will be calculated?"}, {"title": "Write chemical equations", "explain": "A balanced equation conserves the number of atoms of each element.", "try": "Balance Mg + O₂ → MgO using coefficients only.", "check": "2Mg + O₂ → 2MgO. Never change formula subscripts to balance."}, {"title": "Read graphs critically", "explain": "A steeper product–time gradient indicates a faster rate at that moment.", "try": "Sketch two product–time curves with the same final product but different initial rates.", "check": "The faster curve levels off sooner at the same final height."}, {"title": "Calculate with units", "explain": "State the relationship, substitute values and carry units through the calculation.", "try": "Calculate concentration when 0.20 mol solute makes 0.50 L solution.", "check": "c = n/V = 0.40 mol L⁻¹; distinguish volume of solution from volume of solvent."}], "practice": [{"question": "A reaction produces 24 cm³ gas in 30 s. Calculate its average rate and explain one limitation of this average.", "hint": "Divide change in volume by time; consider whether rate stays constant.", "answer": "24 ÷ 30 = 0.80 cm³ s⁻¹. This averages the whole interval and can hide a rapid start followed by slowing. State both the value and unit.", "extend": "Explain how an initial-rate estimate could be obtained from a graph."}, {"question": "Why does powdered calcium carbonate usually react faster than equal-mass large chips under otherwise identical conditions?", "hint": "Think about exposed particles, not a change in chemical identity.", "answer": "Powder has a greater surface area exposed to acid, allowing more successful collisions per second. It is not because the particles inside each grain have become smaller atoms.", "extend": "Predict whether the final gas volume changes if the same limiting amount reacts completely."}, {"question": "A claim says a fuel is carbon neutral because plants absorb CO₂. What evidence would you request?", "hint": "Look beyond the moment of combustion.", "answer": "Request lifecycle evidence for cultivation, fertiliser, processing, transport, land-use change and regrowth. Uptake alone does not establish a zero net impact.", "extend": "Compare the boundaries used in two lifecycle studies."}], "resources": [{"title": "Royal Society of Chemistry Education", "url": "https://edu.rsc.org/", "kind": "Read", "task": "Choose a sustainability article. Record one chemical explanation and one evidence-based question."}, {"title": "PhET interactive simulations", "url": "https://phet.colorado.edu/", "kind": "Try", "task": "Find Balancing Chemical Equations. Explain why changing coefficients preserves substances."}, {"title": "Royal Institution science films", "url": "https://www.rigb.org/explore-science", "kind": "Watch", "task": "Choose a chemistry film and pause to predict an outcome. Do not recreate demonstrations at home."}, {"title": "Qualifications Scotland past papers", "url": "https://www.sqa.org.uk/pastpapers/findpastpaper.htm", "kind": "Try", "task": "Select your level and compare an attempted chemistry answer with its marking instructions."}, {"title": "Understanding Standards", "url": "https://www.understandingstandards.org.uk/", "kind": "Read", "task": "Find Chemistry and discuss why evidence earns credit. Some materials are restricted to staff."}], "ipad": [{"title": "Particle explanation", "steps": ["Draw a labelled before-and-after particle model.", "Record a 40-second explanation of what changes.", "Add captions distinguishing particles from substances."], "evidence": "An annotated explanation, not a photograph without reasoning."}, {"title": "Data storyteller", "steps": ["Enter a teacher-provided dataset in Numbers.", "Create a labelled scatter graph with appropriate units.", "Annotate the trend and one anomalous result."], "evidence": "A graph plus an evidence-based conclusion."}, {"title": "Retrieval cards", "steps": ["Create six question cards after a lesson.", "Record your explanation before checking notes.", "Correct one misconception in a different colour."], "evidence": "A dated set showing how your explanation improved."}], "careers": [{"title": "Laboratory technician", "linkToLearning": "Accurate measurement, records and safety support reliable testing.", "nextStep": "Explore college science routes and laboratory apprenticeships on My World of Work."}, {"title": "Chemical engineer", "linkToLearning": "Reaction rates and energy connect to efficient industrial processes.", "nextStep": "Compare accredited university chemical engineering entry requirements."}, {"title": "Environmental analyst", "linkToLearning": "Chemical evidence informs water quality and pollution decisions.", "nextStep": "Investigate college environmental science and university chemistry pathways."}, {"title": "Pharmacy and pharmaceutical science", "linkToLearning": "Structures, concentration and quality assurance support medicines work.", "nextStep": "Compare pharmacist degree routes with pharmacy support and technician training."}], "parentTip": "Ask your young person to explain one everyday change using particles. Encourage a clear explanation and a question for class; avoid trying chemical demonstrations at home.", "vocabulary": [{"en": "Atom", "ar": "ذرة"}, {"en": "Element", "ar": "عنصر"}, {"en": "Compound", "ar": "مركب"}, {"en": "Reaction", "ar": "تفاعل"}, {"en": "Acid", "ar": "حمض"}, {"en": "Alkali", "ar": "قلوي"}, {"en": "Concentration", "ar": "تركيز"}, {"en": "Evidence", "ar": "دليل"}], "sourceNotes": [{"title": "Qualifications Scotland — Chemistry", "url": "https://www.sqa.org.uk/sqa/45720.html"}, {"title": "Qualifications Scotland — National 5 Chemistry", "url": "https://www.sqa.org.uk/sqa/45722.html"}, {"title": "Qualifications Scotland — Higher Chemistry", "url": "https://www.sqa.org.uk/sqa/46504.html"}], "visual": {"title": "Count atoms, not just symbols", "question": "The equation is 2H₂ + O₂ → 2H₂O. Count each type of atom on both sides. Why must the small formula numbers stay unchanged?", "answer": "Both sides contain 4 hydrogen atoms and 2 oxygen atoms. Coefficients change the amount of each substance; changing a formula subscript changes the substance.", "svg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 520 360\" role=\"img\" aria-label=\"Count atoms, not just symbols\"><rect width=\"520\" height=\"360\" fill=\"#f2f7f8\"/><g font-family=\"Arial\" font-size=\"25\" fill=\"#19354a\"><text x=\"45\" y=\"80\">2H₂ + O₂</text><text x=\"340\" y=\"80\">2H₂O</text><text x=\"235\" y=\"80\">→</text></g><g stroke=\"#19354a\" stroke-width=\"2\"><circle cx=\"65\" cy=\"165\" r=\"18\" fill=\"#9ed6dc\"/><circle cx=\"105\" cy=\"165\" r=\"18\" fill=\"#9ed6dc\"/><circle cx=\"65\" cy=\"220\" r=\"18\" fill=\"#9ed6dc\"/><circle cx=\"105\" cy=\"220\" r=\"18\" fill=\"#9ed6dc\"/><circle cx=\"170\" cy=\"170\" r=\"25\" fill=\"#eb7b72\"/><circle cx=\"170\" cy=\"225\" r=\"25\" fill=\"#eb7b72\"/><circle cx=\"350\" cy=\"185\" r=\"25\" fill=\"#eb7b72\"/><circle cx=\"320\" cy=\"160\" r=\"18\" fill=\"#9ed6dc\"/><circle cx=\"380\" cy=\"160\" r=\"18\" fill=\"#9ed6dc\"/><circle cx=\"440\" cy=\"250\" r=\"25\" fill=\"#eb7b72\"/><circle cx=\"410\" cy=\"225\" r=\"18\" fill=\"#9ed6dc\"/><circle cx=\"470\" cy=\"225\" r=\"18\" fill=\"#9ed6dc\"/></g><g font-family=\"Arial\" font-size=\"18\"><text x=\"40\" y=\"310\">Blue: hydrogen</text><text x=\"290\" y=\"310\">Coral: oxygen</text></g></svg>"}}, "physics": {"id": "physics", "name": "Physics", "strapline": "Understand the forces shaping our world.", "intro": "Use models, measurements and mathematics to explain motion, energy and technology. Suggested BGE projects need departmental review. National course content is separated from optional exploration. All physical investigations require teacher direction and school safety procedures; independent tasks here use supplied data, diagrams or simulations.", "bge": [{"title": "Motion around Govan", "question": "How can we describe a journey?", "learn": ["Distinguish distance and displacement.", "Calculate average speed.", "Interpret motion graphs."], "task": "Use a fictional bus timetable to calculate average speed between stops. Explain the assumptions.", "extend": "Sketch why a journey’s average speed differs from its maximum speed."}, {"title": "Powering our future", "question": "Where does useful energy go?", "learn": ["Describe energy transfers.", "Compare power and energy.", "Interpret efficiency data."], "task": "Draw an energy-transfer diagram for a lamp and explain the meaning of wasted energy.", "extend": "Compare two lighting options using energy and lifetime data."}, {"title": "Signals and sound", "question": "How does information travel?", "learn": ["Describe frequency and amplitude.", "Identify wave features.", "Link models to communication."], "task": "Annotate a supplied wave diagram and write what would change for a higher-pitched sound.", "extend": "Explain why sound cannot cross a vacuum."}, {"title": "Space explorers", "question": "What can light tell us about space?", "learn": ["Use the idea of a light-year.", "Compare stars and planets.", "Read astronomical scales."], "task": "Create a scale comparison from NASA data with units and an explanation of what is omitted.", "extend": "Explain why seeing a distant galaxy means seeing its past."}], "senior": [{"level": "National 3 / National 4", "title": "Physics", "areas": ["Electricity and Energy", "Waves and Radiation", "Dynamics and Space"], "explain": "Build explanations through numerical work and enquiry. National 4 adds an investigation assignment.", "assessment": "Internally assessed units, with added value at National 4; pass/fail.", "source": {"title": "Qualifications Scotland — Physics", "url": "https://www.sqa.org.uk/sqa/45912.html"}}, {"level": "National 5", "title": "National 5 Physics", "areas": ["Dynamics", "Space", "Electricity", "Properties of Matter", "Waves", "Radiation"], "explain": "Connect six content areas through problem solving, experimental evidence, equations and units.", "assessment": "Question paper and assignment. This hub’s calculations are practice examples, not live assignment responses.", "source": {"title": "Qualifications Scotland — National 5 Physics", "url": "https://www.sqa.org.uk/sqa/47430.html"}}, {"level": "Higher", "title": "Higher Physics", "areas": ["Our Dynamic Universe", "Particles and Waves", "Electricity", "Researching Physics skills"], "explain": "Extend motion, gravitation, waves, particles, circuits and fields using mathematical models. Researching Physics supports enquiry.", "assessment": "Question paper and assignment; use the current session specification.", "source": {"title": "Qualifications Scotland — Higher Physics", "url": "https://www.sqa.org.uk/sqa/45912.html"}}], "skills": [{"title": "Select a relationship", "explain": "List quantities, units and the unknown before choosing an equation.", "try": "Find acceleration for velocity changing from 4 to 16 m s⁻¹ in 3 s.", "check": "a = (16 − 4)/3 = 4 m s⁻²."}, {"title": "Read a circuit", "explain": "Trace connected points, identifying series paths and parallel branches.", "try": "Explain where a voltmeter measures the potential difference across a component.", "check": "It connects in parallel; an ammeter measures current in series."}, {"title": "Use a graph", "explain": "Gradient represents change in the vertical quantity divided by change in the horizontal quantity.", "try": "Explain the gradient of a velocity–time graph.", "check": "It is acceleration, with units m s⁻²; area represents displacement."}, {"title": "Evaluate measurement", "explain": "Resolution, random variation and systematic effects influence results.", "try": "Compare five repeated timings with one reading.", "check": "Repeats help assess random variation; they do not automatically remove systematic error."}], "practice": [{"question": "A 12 V supply passes 0.50 A through a resistor. Calculate resistance and power.", "hint": "Use V = IR and P = VI.", "answer": "R = 12/0.50 = 24 Ω. P = 12 × 0.50 = 6.0 W. Include both units and show substitution.", "extend": "Predict the current if voltage doubles and resistance stays constant."}, {"question": "A wave has frequency 5 Hz and wavelength 2 m. What is its speed? Explain what frequency measures.", "hint": "Use v = fλ.", "answer": "v = 5 × 2 = 10 m s⁻¹. Frequency is the number of complete oscillations per second, not the distance between peaks.", "extend": "If speed stays constant and frequency doubles, calculate the new wavelength."}, {"question": "Two identical balls are dropped from the same height; one experiences substantial air resistance. Must they arrive together?", "hint": "Separate the ideal model from actual forces.", "answer": "In the ideal no-air-resistance model, acceleration is the same. With substantial air resistance, net force and acceleration can differ, so arrival times need not match.", "extend": "Explain which measurements could test whether air resistance matters."}], "resources": [{"title": "PhET simulations", "url": "https://phet.colorado.edu/", "kind": "Try", "task": "Explore Circuit Construction Kit virtually and record a prediction before changing a circuit."}, {"title": "NASA learning resources", "url": "https://www.nasa.gov/learning-resources/", "kind": "Watch", "task": "Choose a space explanation and distinguish an observation from its interpretation."}, {"title": "Institute of Physics", "url": "https://www.iop.org/explore-physics", "kind": "Read", "task": "Connect one physics story to a course concept and explain its relevance."}, {"title": "Royal Institution films", "url": "https://www.rigb.org/explore-science", "kind": "Watch", "task": "Find a physics talk and create three retrieval questions; do not reproduce demonstrations."}, {"title": "Official past papers", "url": "https://www.sqa.org.uk/pastpapers/findpastpaper.htm", "kind": "Try", "task": "Attempt one calculation before revealing the official marking instructions."}], "ipad": [{"title": "Explain a graph", "steps": ["Import a teacher-provided motion graph.", "Annotate three intervals with physical meaning.", "Record a narrated explanation including units."], "evidence": "A labelled graph and a 60-second explanation."}, {"title": "Simulation investigation", "steps": ["Choose a teacher-approved simulation variable.", "Capture three settings and record outcomes in a table.", "State a trend and the limits of the model."], "evidence": "Screenshots support an explanation, rather than replace one."}, {"title": "Equation clinic", "steps": ["Write a worked solution with quantities and units.", "Use screen recording to explain each step.", "Correct a deliberate unit error in a second example."], "evidence": "Two solutions showing reasoning and checking."}], "careers": [{"title": "Renewable energy technician", "linkToLearning": "Electrical and energy knowledge supports installation and maintenance.", "nextStep": "Explore engineering college courses and apprenticeships."}, {"title": "Medical physicist", "linkToLearning": "Radiation and measurement support diagnosis and treatment technology.", "nextStep": "Investigate physics degrees and professional clinical training requirements."}, {"title": "Software and data specialist", "linkToLearning": "Modelling and problem solving transfer into digital work.", "nextStep": "Compare computing apprenticeships, college and university pathways."}, {"title": "Civil or mechanical engineer", "linkToLearning": "Forces, materials and motion shape safe designs.", "nextStep": "Compare engineering disciplines and their entry requirements."}], "parentTip": "Ask for a diagram explaining a familiar technology. Praise the use of units and evidence, and encourage questions when a model does not match the real world.", "vocabulary": [{"en": "Force", "ar": "قوة"}, {"en": "Energy", "ar": "طاقة"}, {"en": "Power", "ar": "قدرة"}, {"en": "Wave", "ar": "موجة"}, {"en": "Speed", "ar": "سرعة"}, {"en": "Current", "ar": "تيار"}, {"en": "Voltage", "ar": "جهد كهربائي"}, {"en": "Radiation", "ar": "إشعاع"}], "sourceNotes": [{"title": "Qualifications Scotland — Physics", "url": "https://www.sqa.org.uk/sqa/45912.html"}, {"title": "Qualifications Scotland — National 5 Physics", "url": "https://www.sqa.org.uk/sqa/47430.html"}, {"title": "Qualifications Scotland — Higher Physics", "url": "https://www.sqa.org.uk/sqa/45912.html"}], "visual": {"title": "Read a distance–time graph", "question": "A person travels 20 m in 10 s, waits for 5 s, then travels another 20 m in 5 s. Which section has the greatest speed?", "answer": "The final section: 20 m ÷ 5 s = 4 m/s. The first section is 2 m/s. The horizontal section represents no change in distance: the person is stationary.", "svg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 520 360\" role=\"img\" aria-label=\"Read a distance–time graph\"><rect width=\"520\" height=\"360\" fill=\"#f2f7f8\"/><path d=\"M70 290H470M90 310V30\" stroke=\"#19354a\" stroke-width=\"2\"/><path d=\"M90 290L260 180H345L430 70\" fill=\"none\" stroke=\"#394f92\" stroke-width=\"5\"/><g fill=\"#19354a\" font-family=\"Arial\" font-size=\"18\"><text x=\"340\" y=\"333\">Time / s</text><text x=\"15\" y=\"25\">Distance / m</text><text x=\"80\" y=\"315\">0</text><text x=\"245\" y=\"315\">10</text><text x=\"332\" y=\"315\">15</text><text x=\"418\" y=\"315\">20</text><text x=\"55\" y=\"185\">20</text><text x=\"55\" y=\"75\">40</text></g></svg>"}}, "biology": {"id": "biology", "name": "Biology", "strapline": "Explore life, from DNA to ecosystems.", "intro": "Investigate how living systems work and how evidence helps us protect them. BGE units are suggestions for S1–S3, not confirmed Govan courses. Higher Biology and Higher Human Biology are different qualifications. Use simulations and supplied datasets independently; laboratory and fieldwork activities require teacher instructions and school procedures.", "bge": [{"title": "Cells: life’s building blocks", "question": "What do living things have in common?", "learn": ["Identify cell structures.", "Connect structures to functions.", "Compare plant and animal cells."], "task": "Annotate two supplied micrographs and explain how three visible structures help the cell function.", "extend": "Explain why a diagram can show structures that a particular micrograph cannot resolve."}, {"title": "Body systems", "question": "How do systems work together?", "learn": ["Describe digestion and transport.", "Link organs to functions.", "Interpret simple biological data."], "task": "Map the journey of oxygen from air to a respiring muscle cell.", "extend": "Explain why breathing and cellular respiration are different processes."}, {"title": "Govan biodiversity", "question": "How could we investigate an ecosystem?", "learn": ["Recognise habitats and communities.", "Interpret food webs.", "Plan representative sampling."], "task": "Plan a school-approved biodiversity survey on paper, identifying sampling locations and limitations.", "extend": "Explain how repeated sampling could strengthen a comparison."}, {"title": "Genes and choices", "question": "Why are individuals different?", "learn": ["Describe inheritance.", "Distinguish genes and environment.", "Evaluate biological claims."], "task": "Compare two fictional claims about inherited characteristics and identify missing evidence.", "extend": "Discuss why a genetic association does not necessarily establish a simple cause."}], "senior": [{"level": "National 3 / National 4", "title": "Biology", "areas": ["Cell Biology", "Multicellular Organisms", "Life on Earth"], "explain": "Develop biological knowledge and practical enquiry. National 4 includes a Biology assignment as added value.", "assessment": "Internally assessed units; added value at National 4; pass/fail.", "source": {"title": "Qualifications Scotland — Biology", "url": "https://www.sqa.org.uk/sqa/47427.html"}}, {"level": "National 5", "title": "National 5 Biology", "areas": ["Cell Biology", "Multicellular Organisms", "Life on Earth"], "explain": "Study cellular processes, reproduction, inheritance, transport, ecosystems and human effects through evidence.", "assessment": "Question paper and assignment under the current specification.", "source": {"title": "Qualifications Scotland — National 5 Biology", "url": "https://www.sqa.org.uk/sqa/47427.html"}}, {"level": "Higher", "title": "Higher Biology", "areas": ["DNA and the Genome", "Metabolism and Survival", "Sustainability and Interdependence"], "explain": "Connect molecular processes with adaptation, populations and food production. These are the Higher Biology headings.", "assessment": "Question paper and assignment. Follow teacher conditions for assessed investigations.", "source": {"title": "Qualifications Scotland — Higher Biology", "url": "https://www.sqa.org.uk/sqa/47912.html"}}, {"level": "Higher alternative", "title": "Higher Human Biology", "areas": ["Human Cells", "Physiology and Health", "Neurobiology and Immunology"], "explain": "A separate Higher route with a human focus; it is not an extra unit of Higher Biology. Check whether the school offers this route.", "assessment": "Separate Human Biology question paper and assignment requirements.", "source": {"title": "Qualifications Scotland — Higher Human Biology", "url": "https://www.sqa.org.uk/sqa/47915.html"}}], "skills": [{"title": "Use biological terminology", "explain": "Name the structure or process and link it to a precise function.", "try": "Explain why an enzyme has an optimum temperature.", "check": "Include increased activity up to an optimum and changes to the active site above it."}, {"title": "Plan sampling", "explain": "Representative sampling reduces bias when comparing habitats.", "try": "Design a random quadrat sampling plan for two areas.", "check": "Specify equal sampling effort, random locations, repeats and responsible access."}, {"title": "Interpret variation", "explain": "Variation within a group matters when comparing averages.", "try": "Compare two means alongside their ranges.", "check": "Avoid claiming certainty from overlapping small samples alone."}, {"title": "Explain a food web", "explain": "Arrows show energy transfer from food to consumer.", "try": "Trace two energy pathways from a producer.", "check": "A predator may be affected indirectly when another population changes."}], "practice": [{"question": "A population rises from 80 to 100. Calculate percentage increase.", "hint": "Use the original value as denominator.", "answer": "Increase = 20. Percentage increase = 20/80 × 100 = 25%. Dividing by 100 would describe a different proportion.", "extend": "Explain why percentage change helps compare populations of different starting sizes."}, {"question": "Why is an enzyme less effective well above its optimum temperature?", "hint": "Think about protein shape and substrate binding.", "answer": "High temperature can denature the enzyme, changing its active-site shape so the substrate no longer fits effectively. It is not simply that particles stop moving.", "extend": "Contrast this with the effect of a low temperature."}, {"question": "A field has fewer plant species after herbicide use. Does this prove the herbicide caused the change?", "hint": "Consider comparison sites and other changing factors.", "answer": "It is consistent with an effect but does not prove causation alone. Compare untreated areas, before-and-after data, sampling effort and other changes such as weather or grazing.", "extend": "Design a stronger, ethical observational comparison."}], "resources": [{"title": "YourGenome", "url": "https://www.yourgenome.org/", "kind": "Read", "task": "Choose a DNA explainer and turn it into a labelled sequence of events."}, {"title": "HHMI BioInteractive", "url": "https://www.biointeractive.org/", "kind": "Watch", "task": "Use a teacher-selected animation. Pause and explain what its simplified model leaves out."}, {"title": "NatureScot", "url": "https://www.nature.scot/", "kind": "Read", "task": "Investigate one Scottish habitat and connect a conservation action to ecological evidence."}, {"title": "Royal Society of Biology", "url": "https://www.rsb.org.uk/", "kind": "Read", "task": "Find a biology careers or science resource and record one route you had not considered."}, {"title": "Official past papers", "url": "https://www.sqa.org.uk/pastpapers/findpastpaper.htm", "kind": "Try", "task": "Attempt a data-handling question and use its marking instructions to improve precision."}], "ipad": [{"title": "Cell tour", "steps": ["Annotate a supplied cell image.", "Add a short audio explanation for four structures.", "Include text captions and distinguish evidence from diagram conventions."], "evidence": "An accessible narrated cell guide."}, {"title": "Biodiversity data", "steps": ["Enter a teacher-provided species table.", "Create a chart with a meaningful scale.", "Explain a pattern and a sampling limitation."], "evidence": "A chart and a cautious evidence-based conclusion."}, {"title": "Process animation", "steps": ["Create six slides showing a biological process.", "Use arrows and consistent labels.", "Record narration, then check scientific terms."], "evidence": "A sequence explaining cause and effect."}], "careers": [{"title": "Biomedical scientist", "linkToLearning": "Cell processes and reliable laboratory work support healthcare testing.", "nextStep": "Explore accredited biomedical science degrees and laboratory support routes."}, {"title": "Conservation ranger", "linkToLearning": "Ecology and sampling help manage habitats responsibly.", "nextStep": "Compare college countryside management with university ecology pathways."}, {"title": "Food laboratory technician", "linkToLearning": "Microbiology and quality-control evidence support food production.", "nextStep": "Explore applied science college courses and laboratory apprenticeships."}, {"title": "Nursing and allied health", "linkToLearning": "Understanding human systems supports further professional study.", "nextStep": "Check current entry requirements for distinct regulated healthcare professions."}], "parentTip": "Invite a clear explanation of one living process. Ask “What evidence supports that?” rather than expecting every scientific word to be remembered immediately.", "vocabulary": [{"en": "Cell", "ar": "خلية"}, {"en": "Gene", "ar": "جين"}, {"en": "Enzyme", "ar": "إنزيم"}, {"en": "Habitat", "ar": "موطن"}, {"en": "Species", "ar": "نوع"}, {"en": "Inheritance", "ar": "وراثة"}, {"en": "Respiration", "ar": "تنفس خلوي"}, {"en": "Biodiversity", "ar": "تنوع حيوي"}], "sourceNotes": [{"title": "Qualifications Scotland — Biology", "url": "https://www.sqa.org.uk/sqa/47427.html"}, {"title": "Qualifications Scotland — National 5 Biology", "url": "https://www.sqa.org.uk/sqa/47427.html"}, {"title": "Qualifications Scotland — Higher Biology", "url": "https://www.sqa.org.uk/sqa/47912.html"}, {"title": "Qualifications Scotland — Higher Human Biology", "url": "https://www.sqa.org.uk/sqa/47915.html"}], "visual": {"title": "Follow energy through a food chain", "question": "Grass → rabbit → fox. What do the arrows represent? Predict a possible effect of a fall in rabbit numbers, and explain why it is a prediction rather than a certainty.", "answer": "Arrows show the direction of energy transfer from food to consumer. Fewer rabbits could reduce food for foxes and grazing on grass. Other foods, predators and conditions also affect populations.", "svg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 520 360\" role=\"img\" aria-label=\"Follow energy through a food chain\"><rect width=\"520\" height=\"360\" fill=\"#f2f7f8\"/><g font-family=\"Arial\" fill=\"#19354a\"><rect x=\"25\" y=\"110\" width=\"125\" height=\"90\" rx=\"14\" fill=\"#cde4bf\"/><rect x=\"195\" y=\"110\" width=\"125\" height=\"90\" rx=\"14\" fill=\"#f5dfb1\"/><rect x=\"365\" y=\"110\" width=\"125\" height=\"90\" rx=\"14\" fill=\"#f2c1ad\"/><g font-size=\"24\"><text x=\"58\" y=\"164\">Grass</text><text x=\"220\" y=\"164\">Rabbit</text><text x=\"409\" y=\"164\">Fox</text><text x=\"162\" y=\"164\">→</text><text x=\"333\" y=\"164\">→</text></g><text x=\"70\" y=\"260\" font-size=\"20\">Direction of energy transfer</text></g></svg>"}}, "graphic-communication": {"id": "graphic-communication", "name": "Graphic Communication", "strapline": "Make ideas clear. Make design matter.", "intro": "Communicate technical information accurately and visual messages convincingly. Suggested BGE projects explore drawing, digital design and responsible communication. They are not confirmed school units. Senior Phase combines technical accuracy with visual impact; software is a tool, not the learning goal. Original practice tasks must not be submitted as live assessed assignments.", "bge": [{"title": "Draw it so someone can make it", "question": "Why are several views useful?", "learn": ["Distinguish 2D and 3D views.", "Use line conventions.", "Apply scale."], "task": "Sketch a simple storage block from the front, top and side. Align corresponding features.", "extend": "Explain which hidden detail cannot be understood from a single photograph."}, {"title": "Messages that work", "question": "How does layout guide a reader?", "learn": ["Recognise hierarchy.", "Use contrast and alignment.", "Design for accessibility."], "task": "Create a school-event poster using three levels of information and explain the reading order.", "extend": "Test whether the message remains understandable in greyscale."}, {"title": "From sketch to model", "question": "How can a model improve an idea?", "learn": ["Develop pictorial sketches.", "Recognise CAD modelling features.", "Evaluate dimensions."], "task": "Plan a simple phone stand on paper or approved CAD software, recording dimensions and assumptions.", "extend": "Explain a modelling limitation such as material flexibility."}, {"title": "Data with integrity", "question": "Can a graphic mislead?", "learn": ["Choose suitable charts.", "Label data honestly.", "Identify misleading scales."], "task": "Redesign a distorted bar chart with a zero baseline and clear source information.", "extend": "Compare the effect of changing scale with changing the underlying data."}], "senior": [{"level": "National 4", "title": "National 4 Graphic Communication", "areas": ["2D Graphic Communication", "3D and Pictorial Graphic Communication", "Added-value assignment"], "explain": "Develop manual and digital communication skills through familiar and straightforward tasks.", "assessment": "Internally assessed units and added-value assignment; pass/fail.", "source": {"title": "Qualifications Scotland — National 4 Graphic Communication", "url": "https://www.sqa.org.uk/sqa/45907.html"}}, {"level": "National 5", "title": "National 5 Graphic Communication", "areas": ["2D Graphic Communication", "3D and Pictorial Graphic Communication"], "explain": "Apply drawing conventions, CAD, colour, layout and presentation to communicate to a defined audience.", "assessment": "Question paper and assignment. Teacher supervision and national conditions apply.", "source": {"title": "Qualifications Scotland — National 5 Graphic Communication", "url": "https://www.sqa.org.uk/sqa/45653.html"}}, {"level": "Higher", "title": "Higher Graphic Communication", "areas": ["2D Graphic Communication", "3D and Pictorial Graphic Communication"], "explain": "Handle more complex technical graphics and promotional communication, justifying design decisions.", "assessment": "Question paper and assignment; use the current official task and specification.", "source": {"title": "Qualifications Scotland — Higher Graphic Communication", "url": "https://www.sqa.org.uk/sqa/47929.html"}}], "skills": [{"title": "Orthographic accuracy", "explain": "Aligned views describe the same object from different directions.", "try": "Check that a hole has matching position in adjacent views.", "check": "Corresponding widths, heights and depths agree; hidden detail uses the appropriate convention."}, {"title": "Scale and dimensions", "explain": "A drawing scale changes representation, not the real object.", "try": "Draw a 120 mm edge at 1:2.", "check": "Its drawn length is 60 mm; its dimension label still gives the real 120 mm."}, {"title": "Visual hierarchy", "explain": "Size, placement, contrast and spacing guide attention.", "try": "Identify the first three things a reader notices in a poster.", "check": "The order should match the communication purpose and remain legible."}, {"title": "Evaluate a CAD model", "explain": "A successful model satisfies the brief and supports later communication.", "try": "Review feature order and dimensions in a supplied model.", "check": "Explain how an edit could affect dependent features rather than merely naming commands."}], "practice": [{"question": "A product is 80 mm wide. How wide should it appear at scale 2:1, and what dimension should be written?", "hint": "Separate drawing size from actual size.", "answer": "Draw it 160 mm wide, but label the real width as 80 mm. A dimension communicates the object, not the enlarged paper measurement.", "extend": "Calculate its drawn width at 1:4."}, {"question": "A poster uses pale yellow text on white, four decorative fonts and equal-sized headings. Suggest two justified improvements.", "hint": "Connect decisions to readability and hierarchy.", "answer": "Increase text-background contrast and establish a limited, consistent type hierarchy. This improves legibility and helps the reader find the main message before details.", "extend": "Test the redesign on an iPad at normal viewing size."}, {"question": "Why can a photorealistic rendered image fail to communicate manufacturing information?", "hint": "Consider what a maker needs.", "answer": "A render can show appearance but may omit exact dimensions, hidden details, tolerances and technical conventions. Add appropriate technical drawings rather than assuming realism guarantees accuracy.", "extend": "Identify a case where a render is still the most useful communication."}], "resources": [{"title": "V&A learning", "url": "https://www.vam.ac.uk/learn", "kind": "Read", "task": "Choose a designed object and explain how form communicates its purpose."}, {"title": "Design Museum learning", "url": "https://designmuseum.org/learning", "kind": "Read", "task": "Study a design story and identify user, need, constraint and response."}, {"title": "Autodesk education", "url": "https://www.autodesk.com/education/educators", "kind": "Watch", "task": "Explore a teacher-selected CAD tutorial. School access and software arrangements may be required."}, {"title": "Official past papers", "url": "https://www.sqa.org.uk/pastpapers/findpastpaper.htm", "kind": "Try", "task": "Choose a drawing interpretation question and check dimensions carefully."}, {"title": "Understanding Standards", "url": "https://www.understandingstandards.org.uk/", "kind": "Read", "task": "Review published Graphic Communication examples with your teacher and discuss evidence of quality."}], "ipad": [{"title": "Design iteration", "steps": ["Photograph your own paper sketch.", "Annotate three changes linked to the brief.", "Save a second version with a short comparison."], "evidence": "Two versions showing purposeful improvement."}, {"title": "Technical explainer", "steps": ["Import a permitted object drawing.", "Highlight aligned features across three views.", "Record a captioned explanation of one hidden detail."], "evidence": "An annotated interpretation, with the original source acknowledged."}, {"title": "Accessibility audit", "steps": ["Open your poster on an iPad.", "Check text size, contrast and reading order.", "Ask a peer to locate key information and record revisions."], "evidence": "A before-and-after layout with evidence of testing."}], "careers": [{"title": "CAD technician", "linkToLearning": "Accurate views and modelling support manufacturing and construction.", "nextStep": "Explore college CAD and engineering technician routes."}, {"title": "Architectural technologist", "linkToLearning": "Technical communication links design intent to building information.", "nextStep": "Compare college and university architectural technology pathways."}, {"title": "Graphic designer", "linkToLearning": "Hierarchy, typography and audience awareness create visual messages.", "nextStep": "Build a process portfolio and investigate college design courses."}, {"title": "Product designer", "linkToLearning": "Models and drawings communicate functional ideas.", "nextStep": "Compare design apprenticeships where available and university product design entry requirements."}], "parentTip": "Ask your young person to explain who a graphic is for and what the audience must understand. Discuss improvements to their own designs without doing the design for them.", "vocabulary": [{"en": "Drawing", "ar": "رسم"}, {"en": "Scale", "ar": "مقياس"}, {"en": "Dimension", "ar": "بُعد"}, {"en": "View", "ar": "مسقط"}, {"en": "Model", "ar": "نموذج"}, {"en": "Contrast", "ar": "تباين"}, {"en": "Layout", "ar": "تخطيط"}, {"en": "Design", "ar": "تصميم"}], "sourceNotes": [{"title": "Qualifications Scotland — National 4 Graphic Communication", "url": "https://www.sqa.org.uk/sqa/45907.html"}, {"title": "Qualifications Scotland — National 5 Graphic Communication", "url": "https://www.sqa.org.uk/sqa/45653.html"}, {"title": "Qualifications Scotland — Higher Graphic Communication", "url": "https://www.sqa.org.uk/sqa/47929.html"}], "visual": {"title": "One object, two views", "question": "A rectangular block is 40 mm wide, 30 mm high and 20 mm deep. Which dimensions are shown in the front elevation and in the plan?", "answer": "Front elevation: width 40 mm and height 30 mm. Plan: width 40 mm and depth 20 mm. Orthographic views describe the same object from different directions.", "svg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 520 360\" role=\"img\" aria-label=\"One object, two views\"><rect width=\"520\" height=\"360\" fill=\"#f2f7f8\"/><g stroke=\"#286f86\" stroke-width=\"3\" fill=\"#d9edf1\"><rect x=\"65\" y=\"60\" width=\"200\" height=\"100\"/><rect x=\"65\" y=\"190\" width=\"200\" height=\"150\"/></g><g fill=\"#19354a\" font-family=\"Arial\" font-size=\"20\"><text x=\"300\" y=\"115\">Plan</text><text x=\"300\" y=\"135\">40 × 20 mm</text><text x=\"300\" y=\"250\">Front elevation</text><text x=\"300\" y=\"277\">40 × 30 mm</text></g></svg>"}}, "woodwork": {"id": "woodwork", "name": "Woodwork", "strapline": "Measure carefully. Make with purpose.", "intro": "Explore materials, craftsmanship and responsible manufacture. BGE projects are suggestions only. Woodwork learning at home should focus on drawings, material choices and evaluation: tools, machines, finishes and practical making require teacher direction and school workshop safety procedures. National 4 and National 5 Practical Woodworking are genuine routes; there is no Higher Practical Woodworking.", "bge": [{"title": "Wood as a material", "question": "Why choose one timber over another?", "learn": ["Recognise hardwoods and softwoods.", "Compare properties and uses.", "Consider responsible sourcing."], "task": "Create a comparison card for two timbers using appearance, workability and intended use.", "extend": "Explain why hardwood does not mean every hardwood is physically harder than every softwood."}, {"title": "Precision from a plan", "question": "How does accuracy begin before cutting?", "learn": ["Read dimensions.", "Identify reference faces and edges.", "Plan measurement checks."], "task": "Annotate a supplied drawing with a sequence of checks before any teacher-directed making.", "extend": "Explain why repeated measuring from a reliable datum can reduce accumulated error."}, {"title": "Joining ideas", "question": "What makes a joint suitable?", "learn": ["Recognise common woodworking joints.", "Relate joint choice to load and appearance.", "Read assembly drawings."], "task": "Compare two illustrated joints for a small frame and justify a choice without making it at home.", "extend": "Identify a trade-off between appearance, strength and ease of manufacture."}, {"title": "Design for long life", "question": "Can a product be repaired?", "learn": ["Consider durability.", "Evaluate material efficiency.", "Recognise finishing purposes."], "task": "Evaluate a wooden school object from photographs: identify one repair or maintenance opportunity.", "extend": "Produce a paper cutting layout that reduces offcuts."}], "senior": [{"level": "National 4", "title": "National 4 Practical Woodworking", "areas": ["Flat-frame Construction", "Carcase Construction", "Machining and Finishing", "Making a Finished Product — added value"], "explain": "Develop practical skills, knowledge of materials and safe working with supervision.", "assessment": "Internally assessed units and added-value practical activity; pass/fail.", "source": {"title": "Qualifications Scotland — National 4 Practical Woodworking", "url": "https://www.sqa.org.uk/sqa/45662.html"}}, {"level": "National 5", "title": "National 5 Practical Woodworking", "areas": ["Flat-frame construction", "Carcase construction", "Machining and finishing", "Practical activity including case study"], "explain": "Apply accurate marking out, manufacture, assembly and finishing with knowledge of tools and materials.", "assessment": "The question paper was removed from session 2025–26. Current assessment is the practical activity, including a case study; use the current specification.", "source": {"title": "Qualifications Scotland — National 5 Practical Woodworking", "url": "https://www.sqa.org.uk/sqa/45662.html"}}, {"level": "Progression — different course", "title": "Higher Design and Manufacture", "areas": ["Design", "Materials and manufacturing", "Design evaluation"], "explain": "A possible related progression where offered, rather than a Higher Woodworking qualification. It adds substantial design and analytical work.", "assessment": "A distinct qualification with its own question paper and assignment requirements. Discuss readiness and school availability.", "source": {"title": "Qualifications Scotland — Higher Design and Manufacture", "url": "https://www.sqa.org.uk/sqa/45645.html"}}], "skills": [{"title": "Read a working drawing", "explain": "Identify overall and component dimensions before choosing a sequence.", "try": "Highlight the thickness, width and length of one component.", "check": "Units and real dimensions are clear; do not measure a screen image as though it were full size."}, {"title": "Plan accurate work", "explain": "Reference surfaces and planned checks support consistent results.", "try": "Write a checking sequence for a fictional frame before assembly.", "check": "Check dimensions, squareness and matching components before irreversible work."}, {"title": "Explain a joint", "explain": "A joint choice should suit the product and direction of loading.", "try": "Annotate where two components meet in a supplied drawing.", "check": "State why the selected joint fits the task, not merely its name."}, {"title": "Evaluate workmanship", "explain": "Use evidence such as fit, alignment, finish and compliance with dimensions.", "try": "Write a specific evaluation of a teacher-provided sample photograph.", "check": "Separate what is visible from what would need physical measurement."}], "practice": [{"question": "A frame drawing specifies two rails of 240 mm and two of 180 mm. Is 840 mm timber necessarily enough?", "hint": "Think beyond the sum of the finished parts.", "answer": "The finished lengths total 840 mm, but cutting allowance, defects, joint requirements and stock preparation may require more. Confirm the cutting list and teacher-approved plan before manufacture.", "extend": "Sketch a stock layout including a stated cutting allowance."}, {"question": "Why should a component be checked for squareness before final assembly?", "hint": "Consider consequences of an early error.", "answer": "An out-of-square component can distort the assembly, create gaps and prevent correct fitting. Checking before final assembly allows correction at a stage when it may still be practical.", "extend": "Identify two other checks needed before assembly."}, {"question": "A polished surface looks attractive. Does this prove a product is well made?", "hint": "Distinguish appearance from function.", "answer": "No. Check dimensions, joint fit, stability, suitability for use and finish quality. A good-looking surface may hide weak joints or inaccurate components.", "extend": "Create a balanced evaluation checklist with measurable criteria."}], "resources": [{"title": "Forestry and Land Scotland learning", "url": "https://forestryandland.gov.scot/learn", "kind": "Read", "task": "Investigate Scottish timber and explain one connection between forest management and products."}, {"title": "Design Museum", "url": "https://designmuseum.org/learning", "kind": "Read", "task": "Examine a product story and identify a material decision."}, {"title": "V&A collections and learning", "url": "https://www.vam.ac.uk/learn", "kind": "Read", "task": "Study furniture construction through an object record and infer its intended use."}, {"title": "Practical Woodworking assessment guidance", "url": "https://www.sqa.org.uk/sqa/45662.html", "kind": "Watch", "task": "Open the official practical-activity video guidance with your teacher; it explains current assessment."}, {"title": "Apprenticeships Scotland", "url": "https://www.apprenticeships.scot/", "kind": "Read", "task": "Compare joinery and manufacturing routes, recording employer and training expectations."}], "ipad": [{"title": "Plan annotation", "steps": ["Import a teacher-provided working drawing.", "Colour-code components and mark dimensions.", "Record a short explanation of the assembly order."], "evidence": "A plan that communicates understanding before practical work."}, {"title": "Craftsmanship record", "steps": ["With permission, photograph only your own school workshop work at safe checkpoints.", "Annotate a measurement or quality check.", "Explain one improvement before the next supervised stage."], "evidence": "A private process record without classmates or personal information."}, {"title": "Material choice board", "steps": ["Collect permitted images of two timber options.", "Compare properties, source and suitability.", "Write a justified recommendation for a brief."], "evidence": "A sourced design decision, not an unsupervised making task."}], "careers": [{"title": "Joinery apprenticeship", "linkToLearning": "Measurement and construction accuracy support building work.", "nextStep": "Explore Modern Apprenticeship entry and employer requirements."}, {"title": "Furniture maker", "linkToLearning": "Craftsmanship combines material knowledge, design and finish.", "nextStep": "Compare college furniture courses and workshop training."}, {"title": "Manufacturing technician", "linkToLearning": "Drawings, quality checks and processes support production.", "nextStep": "Investigate engineering and manufacturing college pathways."}, {"title": "Product designer", "linkToLearning": "Understanding manufacture improves realistic design decisions.", "nextStep": "Consider related design qualifications and portfolio requirements."}], "parentTip": "Discuss a drawing or material choice at home. Practical workshop tasks must remain teacher-directed; do not encourage pupils to recreate tool or machine operations independently.", "vocabulary": [{"en": "Timber", "ar": "خشب"}, {"en": "Joint", "ar": "وصلة"}, {"en": "Grain", "ar": "ألياف الخشب"}, {"en": "Measure", "ar": "قياس"}, {"en": "Accuracy", "ar": "دقة"}, {"en": "Finish", "ar": "تشطيب"}, {"en": "Frame", "ar": "إطار"}, {"en": "Safety", "ar": "سلامة"}], "sourceNotes": [{"title": "Qualifications Scotland — National 4 Practical Woodworking", "url": "https://www.sqa.org.uk/sqa/45662.html"}, {"title": "Qualifications Scotland — National 5 Practical Woodworking", "url": "https://www.sqa.org.uk/sqa/45662.html"}, {"title": "Qualifications Scotland — Higher Design and Manufacture", "url": "https://www.sqa.org.uk/sqa/45645.html"}]}, "home-economics": {"id": "home-economics", "name": "Home Economics", "strapline": "Skills for food, wellbeing and everyday life.", "intro": "Explore food choices, preparation, sustainability and product development. Home Economics is an umbrella: Practical Cookery and Health and Food Technology are different qualifications. Suggested BGE projects need departmental review. Follow teacher instructions, allergy arrangements and school food-safety procedures for all practical work; independent hub tasks use menus, labels and planning.", "bge": [{"title": "Food and our choices", "question": "What influences what we eat?", "learn": ["Recognise influences on food choice.", "Read food information.", "Respect cultural and individual needs."], "task": "Compare two fictional lunch options using cost, variety and suitability, without labelling a person’s food choices.", "extend": "Identify information needed before planning for a group with allergies."}, {"title": "Kitchen organisation", "question": "Why does planning matter?", "learn": ["Understand hygiene principles.", "Read a recipe sequence.", "Identify cross-contamination risks."], "task": "Reorder a supplied preparation plan and explain two safety-critical stages.", "extend": "Explain why cleaning and separating raw and ready-to-eat foods are different controls."}, {"title": "Food waste detectives", "question": "How can resources go further?", "learn": ["Distinguish date labels.", "Consider storage and portion planning.", "Read waste data."], "task": "Use a fictional household shopping list to propose three waste-reduction changes.", "extend": "Explain why a use-by date should not be treated like a best-before date."}, {"title": "Develop a product", "question": "How do we know a food meets a brief?", "learn": ["Identify user requirements.", "Plan fair sensory comparison.", "Use feedback to refine ideas."], "task": "Design a paper-based snack concept for a stated brief, with ingredients and evaluation criteria.", "extend": "Explain how coded samples could reduce bias in a teacher-organised sensory test."}], "senior": [{"level": "National 3 / National 4", "title": "Practical Cookery", "areas": ["Cookery Skills, Techniques and Processes", "Understanding and Using Ingredients", "Organisational Skills for Cooking"], "explain": "Develop safe practical preparation and organisation. National 4 includes added-value practical work.", "assessment": "Internal assessment, with added value at National 4; pass/fail.", "source": {"title": "Qualifications Scotland — Practical Cookery", "url": "https://www.sqa.org.uk/sqa/45681.html"}}, {"level": "National 5", "title": "National 5 Practical Cookery", "areas": ["Cookery skills and processes", "Ingredients", "Organisation and practical performance"], "explain": "A practical qualification focused on preparation, cooking and presentation. There is no Higher Practical Cookery.", "assessment": "For session 2026–27 the assignment has been removed. Use the current specification for the question paper and practical activity requirements.", "source": {"title": "Qualifications Scotland — National 5 Practical Cookery", "url": "https://www.sqa.org.uk/sqa/45683.html"}}, {"level": "National 4 / National 5", "title": "Health and Food Technology", "areas": ["Food for Health", "Food Product Development", "Contemporary Food Issues"], "explain": "A separate course connecting nutrition, consumer issues and food product development. National 4 includes added value.", "assessment": "National 4 is internally assessed; National 5 uses a question paper and assignment under current conditions.", "source": {"title": "Qualifications Scotland — Health and Food Technology", "url": "https://www.sqa.org.uk/sqa/45740.html"}}, {"level": "Higher", "title": "Higher Health and Food Technology", "areas": ["Food for Health", "Food Product Development", "Contemporary Food Issues"], "explain": "Analyse food needs, functional properties, product development and contemporary issues in greater depth. This is a different route from Practical Cookery.", "assessment": "Question paper and assignment; discuss entry and availability with the department.", "source": {"title": "Qualifications Scotland — Higher Health and Food Technology", "url": "https://www.sqa.org.uk/sqa/47899.html"}}], "skills": [{"title": "Read a label", "explain": "Compare like-for-like quantities and identify the relevant information.", "try": "Compare sugar per 100 g and per portion for two fictional products.", "check": "Explain how portion size can change the apparent comparison."}, {"title": "Plan a workflow", "explain": "Organise tasks so timing, hygiene and resources work together.", "try": "Annotate a teacher-provided plan with storage and cleaning checkpoints.", "check": "Show which tasks can overlap safely and which require separation."}, {"title": "Evaluate a food product", "explain": "Use criteria linked to a brief rather than personal preference alone.", "try": "Write three criteria for a convenient school snack concept.", "check": "Each criterion should be specific enough to evaluate."}, {"title": "Analyse evidence", "explain": "Food claims need reliable evidence and appropriate context.", "try": "Identify the source and audience of a food advertisement.", "check": "Distinguish a marketing claim from evidence and avoid personalised health conclusions."}], "practice": [{"question": "Product A has 12 g sugar per 100 g and a 25 g portion. How much sugar is in that portion?", "hint": "Find one quarter of the per-100 g figure.", "answer": "12 × 25/100 = 3 g. Use the same basis when comparing products; a smaller printed portion can make values look lower.", "extend": "Compare with a product containing 10 g per 100 g in a 40 g portion."}, {"question": "Why is using the same unwashed board for raw chicken and ready-to-eat salad unsafe?", "hint": "The salad has no later cooking step.", "answer": "Microorganisms may transfer from raw poultry to food that will be eaten without further cooking. Follow school procedures for separate equipment, cleaning and hand hygiene.", "extend": "Identify how a workflow plan could prevent that transfer."}, {"question": "A developer asks five friends whether a new food is “the best ever”. Why is this weak evaluation?", "hint": "Consider sample, wording and criteria.", "answer": "The sample is small and unrepresentative, and the leading question encourages praise. Use neutral questions and criteria linked to the brief; teacher-organised coded comparisons can reduce bias.", "extend": "Write two neutral feedback questions."}], "resources": [{"title": "Food Standards Scotland", "url": "https://www.foodstandards.gov.scot/", "kind": "Read", "task": "Find food-safety guidance and explain one rule using its purpose, not just its wording."}, {"title": "Food a fact of life cooking skills", "url": "https://www.foodafactoflife.org.uk/cooking/cooking-skills", "kind": "Watch", "task": "Review a teacher-selected technique resource. Practical use remains supervised and school-directed."}, {"title": "Food a fact of life nutritional analysis", "url": "https://www.foodafactoflife.org.uk/cooking/nutritional-analysis/", "kind": "Try", "task": "Analyse a supplied recipe as a learning exercise; do not use it for personalised dietary advice."}, {"title": "Zero Waste Scotland", "url": "https://www.zerowastescotland.org.uk/", "kind": "Read", "task": "Investigate food-waste prevention and identify a feasible planning change."}, {"title": "Official assessment information", "url": "https://www.sqa.org.uk/sqa/117428.html", "kind": "Read", "task": "Check current assessment changes before using an older Practical Cookery resource."}], "ipad": [{"title": "Workflow designer", "steps": ["Use a teacher-provided recipe on screen.", "Create an ordered timeline with safety checkpoints.", "Explain two sequencing decisions in audio and captions."], "evidence": "A clear preparation plan ready for teacher feedback."}, {"title": "Label comparison", "steps": ["Use supplied food-label images.", "Create a comparison table on a consistent basis.", "Write a cautious conclusion explaining portion size."], "evidence": "A data-based consumer comparison."}, {"title": "Product development journal", "steps": ["Sketch a concept against a stated brief.", "Add teacher-approved feedback from a class activity.", "Show a revised version and justify one change."], "evidence": "A record of design decisions, not live assignment content."}], "careers": [{"title": "Professional cook or chef", "linkToLearning": "Organisation and consistent preparation support hospitality.", "nextStep": "Explore college professional cookery and hospitality apprenticeships."}, {"title": "Food technologist", "linkToLearning": "Product development and evidence underpin food manufacture.", "nextStep": "Compare college food science and university food technology routes."}, {"title": "Environmental health work", "linkToLearning": "Food safety and legislation protect consumers.", "nextStep": "Investigate relevant degree and professional training requirements."}, {"title": "Hospitality management", "linkToLearning": "Resource planning, communication and service work together.", "nextStep": "Explore college hospitality courses and employer training routes."}], "parentTip": "Talk through a shopping list, label or meal plan. Keep discussion respectful of culture, budget and individual needs; school practicals follow agreed allergy and safety procedures.", "vocabulary": [{"en": "Ingredient", "ar": "مكوّن"}, {"en": "Recipe", "ar": "وصفة"}, {"en": "Hygiene", "ar": "نظافة"}, {"en": "Nutrition", "ar": "تغذية"}, {"en": "Allergy", "ar": "حساسية"}, {"en": "Portion", "ar": "حصة"}, {"en": "Evaluation", "ar": "تقييم"}, {"en": "Waste", "ar": "هدر"}], "sourceNotes": [{"title": "Qualifications Scotland — Practical Cookery", "url": "https://www.sqa.org.uk/sqa/45681.html"}, {"title": "Qualifications Scotland — National 5 Practical Cookery", "url": "https://www.sqa.org.uk/sqa/45683.html"}, {"title": "Qualifications Scotland — Health and Food Technology", "url": "https://www.sqa.org.uk/sqa/45740.html"}, {"title": "Qualifications Scotland — Higher Health and Food Technology", "url": "https://www.sqa.org.uk/sqa/47899.html"}]}, "drama": {"id": "drama", "name": "Drama", "strapline": "Find your voice. Shape a story.", "intro": "Explore how performance and production choices communicate meaning. Suggested BGE units develop imagination, collaboration and analysis; they are not confirmed school courses. Senior Phase choices include acting and production roles under national requirements. Use fictional scenarios sensitively, respect others’ boundaries and follow teacher guidance on recording, movement, equipment and performance texts.", "bge": [{"title": "Stories from a stimulus", "question": "How can one image become many stories?", "learn": ["Develop dramatic situations.", "Identify purpose and audience.", "Select dramatic conventions."], "task": "Create a six-moment storyboard from a teacher-approved image, showing a clear change in tension.", "extend": "Explain how changing the order would alter the audience’s understanding."}, {"title": "Voice and character", "question": "How does a character reveal intention?", "learn": ["Explore pace, pause and tone.", "Connect movement to status.", "Use motivation."], "task": "Annotate a short fictional speech with three purposeful vocal decisions.", "extend": "Perform two contrasting interpretations in class and explain what changes."}, {"title": "Backstage storytelling", "question": "How do design choices tell a story?", "learn": ["Identify production roles.", "Connect colour and space to meaning.", "Consider practical constraints."], "task": "Design a paper set and lighting mood board for a short scene, justifying two choices.", "extend": "Explain how a low-budget version could preserve the intended effect."}, {"title": "Watching like a theatre-maker", "question": "What makes evaluation useful?", "learn": ["Separate description from analysis.", "Use specific performance evidence.", "Explain audience impact."], "task": "Watch a permitted extract and record a precise moment, choice and effect.", "extend": "Offer an alternative interpretation supported by the same evidence."}], "senior": [{"level": "National 3 / National 4", "title": "Drama", "areas": ["Drama Skills", "Production Skills", "National 4 added-value performance"], "explain": "Develop and communicate ideas collaboratively through drama and production. National 4 adds a performance task.", "assessment": "Internally assessed units; added value at National 4; pass/fail.", "source": {"title": "Qualifications Scotland — Drama", "url": "https://www.sqa.org.uk/sqa/45712.html"}}, {"level": "National 5", "title": "National 5 Drama", "areas": ["Drama skills", "Production skills", "Performance and evaluation"], "explain": "Explore devising, characterisation and production skills, then evaluate how choices communicate meaning.", "assessment": "Question paper and performance under the current specification; available assessment roles have specific requirements.", "source": {"title": "Qualifications Scotland — National 5 Drama", "url": "https://www.sqa.org.uk/sqa/45714.html"}}, {"level": "Higher", "title": "Higher Drama", "areas": ["Drama skills", "Production skills", "Performance", "Theatre study, analysis and evaluation"], "explain": "Develop more detailed interpretation and analysis of texts and theatre, with practical performance or production skills.", "assessment": "Question paper and performance. Follow the current specification, including revised question-paper guidance.", "source": {"title": "Qualifications Scotland — Higher Drama", "url": "https://www.sqa.org.uk/sqa/46485.html"}}], "skills": [{"title": "Develop a character", "explain": "Connect intention and relationships to visible or audible choices.", "try": "Annotate a line with what the character wants and how voice communicates it.", "check": "Explain the relationship between the choice and audience interpretation."}, {"title": "Build tension", "explain": "Pacing, silence, focus and withheld information shape anticipation.", "try": "Storyboard a scene in which a character notices something others do not.", "check": "State where tension increases and what causes that change."}, {"title": "Justify design", "explain": "Production choices should serve meaning and be feasible.", "try": "Select a colour palette and spatial arrangement for a fictional scene.", "check": "Link each choice to atmosphere or relationship rather than taste alone."}, {"title": "Evaluate precisely", "explain": "Use a specific moment, theatrical terminology and an explained effect.", "try": "Replace “the acting was good” with a three-part evidence statement.", "check": "Name the choice, locate it and explain its impact on meaning."}], "practice": [{"question": "A character says “I am delighted” with a long pause, lowered gaze and flat tone. What might the audience infer?", "hint": "Compare spoken text with performance signals.", "answer": "The contrast may suggest insincerity, disappointment or concealed emotion. Support one interpretation with the pause, gaze and tone; do not assume a single response is guaranteed.", "extend": "Suggest a contrasting delivery that makes the delight convincing."}, {"question": "A scene feels confusing because actors speak simultaneously throughout. Suggest a purposeful revision.", "hint": "Consider focus and dramatic intention.", "answer": "Create moments of clear vocal focus and use overlap selectively to communicate conflict or urgency. Explain which information the audience must hear and when.", "extend": "Explain when sustained overlapping speech might be an intentional choice."}, {"question": "What makes “the blue lighting was effective” an incomplete evaluation?", "hint": "Effective for what purpose, at which moment?", "answer": "It lacks a located example and explanation. For instance, a cold blue wash during the character’s isolation may reinforce distance and loneliness. Support the effect with context.", "extend": "Write an alternative interpretation of the same lighting choice."}], "resources": [{"title": "National Theatre learning", "url": "https://www.nationaltheatre.org.uk/learn-explore/", "kind": "Watch", "task": "Choose an available theatre-making resource and note one rehearsal or design technique."}, {"title": "Royal Shakespeare Company learning", "url": "https://www.rsc.org.uk/learn", "kind": "Read", "task": "Explore a character or text resource and connect language to playable intention."}, {"title": "National Theatre of Scotland", "url": "https://www.nationaltheatrescotland.com/", "kind": "Watch", "task": "Explore a production story or available film; identify how Scottish context shapes meaning."}, {"title": "Scottish Youth Theatre", "url": "https://scottishyouththeatre.org/", "kind": "Read", "task": "Investigate creative opportunities and identify collaboration skills you could develop."}, {"title": "Official past papers", "url": "https://www.sqa.org.uk/pastpapers/findpastpaper.htm", "kind": "Try", "task": "Attempt a Drama analysis question using precise evidence, then check marking guidance."}], "ipad": [{"title": "Character voice journal", "steps": ["Write a brief interpretation of a fictional character.", "Record a permitted short speech with captions.", "Review one vocal choice and record a revision."], "evidence": "Two interpretations plus an explanation of purposeful change."}, {"title": "Production pitch", "steps": ["Create a digital mood board using permitted images.", "Annotate lighting, set and costume choices.", "Record a pitch linked to the scene’s intended meaning."], "evidence": "A sourced design proposal with practical considerations."}, {"title": "Performance review", "steps": ["Use a permitted extract rather than recording others without consent.", "Mark three timestamps containing clear theatrical choices.", "Write a choice–evidence–effect comment for each."], "evidence": "Specific analysis that can inform your own work."}], "careers": [{"title": "Actor or performer", "linkToLearning": "Interpretation, rehearsal and responsiveness support performance.", "nextStep": "Explore college acting, conservatoire and university routes, including audition requirements."}, {"title": "Stage technician", "linkToLearning": "Production planning and communication support safe theatre work.", "nextStep": "Investigate technical theatre college training and entry roles."}, {"title": "Community arts practitioner", "linkToLearning": "Facilitation and creative collaboration support participation.", "nextStep": "Compare youth arts, community work and applied theatre pathways."}, {"title": "Producer or events organiser", "linkToLearning": "Scheduling, teamwork and audience awareness support delivery.", "nextStep": "Explore arts administration, event management and employer experience routes."}], "parentTip": "Ask what a character wants and which performance choice shows it. A useful response notices a specific moment and its effect; confidence grows through manageable rehearsal and constructive feedback.", "vocabulary": [{"en": "Character", "ar": "شخصية"}, {"en": "Stage", "ar": "خشبة المسرح"}, {"en": "Voice", "ar": "صوت"}, {"en": "Movement", "ar": "حركة"}, {"en": "Audience", "ar": "جمهور"}, {"en": "Tension", "ar": "توتر"}, {"en": "Lighting", "ar": "إضاءة"}, {"en": "Rehearsal", "ar": "بروفة"}], "sourceNotes": [{"title": "Qualifications Scotland — Drama", "url": "https://www.sqa.org.uk/sqa/45712.html"}, {"title": "Qualifications Scotland — National 5 Drama", "url": "https://www.sqa.org.uk/sqa/45714.html"}, {"title": "Qualifications Scotland — Higher Drama", "url": "https://www.sqa.org.uk/sqa/46485.html"}]}, "music": {"id": "music", "name": "Music", "strapline": "Listen closely. Create boldly.", "intro": "Develop your musical voice through performing, composing and listening. Suggested BGE experiences are flexible ideas for departmental review. Music and Music Technology are different qualifications. Practice examples here support learning and must not be presented as completed assessed compositions. Respect copyright, recording consent and comfortable listening levels; follow school guidance for equipment and practical sessions.", "bge": [{"title": "Rhythm in everyday life", "question": "How can a pattern develop?", "learn": ["Keep a steady pulse.", "Recognise rhythmic patterns.", "Explore repetition and contrast."], "task": "Create a written eight-bar rhythm using a teacher-approved notation system, showing repetition and one change.", "extend": "Explain how syncopation can challenge the expected beat."}, {"title": "Melody and mood", "question": "Why do melodies feel different?", "learn": ["Recognise pitch contour.", "Explore major and minor sounds.", "Use musical phrasing."], "task": "Sketch the contour of a supplied melody and identify a phrase ending.", "extend": "Compare two interpretations and explain one expressive difference."}, {"title": "Music and identity", "question": "How does music connect communities?", "learn": ["Explore Scottish and global traditions.", "Recognise instruments and timbres.", "Use respectful musical vocabulary."], "task": "Compare two teacher-selected recordings by instrumentation, rhythm and context, avoiding stereotypes.", "extend": "Find how a contemporary musician adapts a traditional influence."}, {"title": "Compose for a scene", "question": "How does music guide a listener?", "learn": ["Connect musical choices to purpose.", "Develop motifs.", "Structure contrasting sections."], "task": "Plan a short soundtrack for a fictional scene, identifying tempo, texture and intended effect.", "extend": "Explain how silence could be more effective than adding another sound."}], "senior": [{"level": "National 3 / National 4", "title": "Music", "areas": ["Performing Skills", "Composing Skills", "Understanding Music", "National 4 added-value performance"], "explain": "Build practical performance, musical creativity and listening knowledge. National 4 adds a performance task.", "assessment": "Internally assessed units and National 4 added value; pass/fail.", "source": {"title": "Qualifications Scotland — Music", "url": "https://www.sqa.org.uk/sqa/45960.html"}}, {"level": "National 5", "title": "National 5 Music", "areas": ["Performing", "Composing", "Understanding music"], "explain": "Develop performance on two instruments, or one instrument and voice, alongside composing and listening skills within national requirements.", "assessment": "Performance, composing assignment and question paper. Teachers confirm repertoire, level and assessment conditions.", "source": {"title": "Qualifications Scotland — National 5 Music", "url": "https://www.sqa.org.uk/sqa/45960.html"}}, {"level": "Higher", "title": "Higher Music", "areas": ["Performing", "Composing", "Understanding music"], "explain": "Increase musical fluency, stylistic understanding and critical listening. Compose and justify choices with more developed musical control.", "assessment": "Performance, composing assignment and question paper under the current specification.", "source": {"title": "Qualifications Scotland — Higher Music", "url": "https://www.sqa.org.uk/sqa/47895.html"}}], "skills": [{"title": "Practise deliberately", "explain": "Choose a small challenge and use a strategy rather than repeating an entire piece unchanged.", "try": "Plan a teacher-agreed practice focus such as one rhythmic transition.", "check": "Can you explain what improved and identify the next precise step?"}, {"title": "Listen with evidence", "explain": "Support a concept with an audible feature.", "try": "Identify an ostinato in a recording and describe its repeated pattern.", "check": "Distinguish a recurring pattern from merely hearing the same instrument."}, {"title": "Develop a motif", "explain": "Variation changes a musical idea while retaining a recognisable relationship.", "try": "Propose a rhythmic or pitch variation of a short original motif.", "check": "Explain what stayed recognisable and what changed."}, {"title": "Read notation in context", "explain": "Connect symbols to sound, timing and expression.", "try": "Annotate a teacher-provided phrase with pulse and dynamics.", "check": "Check whether the notation communicates the intended performance consistently."}], "practice": [{"question": "What is the difference between tempo and dynamics? Give a musical example.", "hint": "One concerns speed; the other concerns loudness.", "answer": "Tempo describes speed, such as a faster pulse. Dynamics describe loudness, such as a crescendo. A passage can become louder without becoming faster.", "extend": "Explain how both could change independently during a dramatic scene."}, {"question": "A short bass pattern repeats beneath changing melodies. Which concept might describe it, and what evidence supports your answer?", "hint": "Listen for a persistent repeated pattern.", "answer": "An ostinato is a repeated musical pattern. Identify the recurring rhythm or pitches in the bass; the instrument alone is not enough evidence.", "extend": "Explain how changing harmony above the pattern could affect the music."}, {"question": "Your composition has four unrelated ideas but no clear shape. Suggest a purposeful improvement.", "hint": "Consider repetition, contrast and return.", "answer": "Develop one motif, contrast it with another section and consider a return such as ABA. This gives the listener relationships to recognise; a structure should serve the intended effect.", "extend": "Describe one variation that could make the returning A section different."}], "resources": [{"title": "Ableton Learning Music", "url": "https://learningmusic.ableton.com/", "kind": "Try", "task": "Explore beat, melody or structure in the browser. Explain a choice before changing it."}, {"title": "BBC Ten Pieces", "url": "https://www.bbc.co.uk/teach/ten-pieces", "kind": "Watch", "task": "Choose an orchestral work and identify two audible features. This is a music resource, not Bitesize."}, {"title": "Royal Scottish National Orchestra", "url": "https://www.rsno.org.uk/", "kind": "Listen", "task": "Explore available learning or performance resources and compare orchestral timbres."}, {"title": "Scottish Chamber Orchestra", "url": "https://www.sco.org.uk/", "kind": "Watch", "task": "Find an available introduction to an instrument or work and connect it to listening vocabulary."}, {"title": "Official course and listening guidance", "url": "https://www.sqa.org.uk/sqa/45960.html", "kind": "Read", "task": "Follow your level to current assessment information, past papers and music guidance."}], "ipad": [{"title": "Practice reflection", "steps": ["Record only your own teacher-agreed performance extract.", "Identify a timestamp showing one strength and one challenge.", "Write a precise next practice step."], "evidence": "A focused reflection; do not share classmates’ recordings without consent."}, {"title": "Listening map", "steps": ["Listen to a permitted recording.", "Create a timeline of sections, textures and instrumental entries.", "Support three annotations with timestamps."], "evidence": "A map showing musical evidence rather than only mood words."}, {"title": "Composition sketchbook", "steps": ["Create a short original idea in approved software or notation.", "Save a version and explain a musical decision.", "Revise one feature after teacher feedback."], "evidence": "A documented learning process separate from assessed coursework."}], "careers": [{"title": "Performer or music educator", "linkToLearning": "Practice, interpretation and communication support musical work.", "nextStep": "Compare college, conservatoire and university entry or audition requirements."}, {"title": "Sound engineer", "linkToLearning": "Listening and understanding musical structure support technical audio work.", "nextStep": "Explore distinct sound production and music technology college routes."}, {"title": "Arts administrator", "linkToLearning": "Organisation and audience knowledge support events and ensembles.", "nextStep": "Investigate creative industries courses, entry roles and work experience."}, {"title": "Composer or media musician", "linkToLearning": "Developing musical ideas serves film, games and performance.", "nextStep": "Build a portfolio and explore composition or commercial music routes."}], "parentTip": "Ask your young person to play or explain one small musical idea and describe their next step. Encourage focused, teacher-agreed practice rather than judging progress by volume or speed.", "vocabulary": [{"en": "Rhythm", "ar": "إيقاع"}, {"en": "Melody", "ar": "لحن"}, {"en": "Tempo", "ar": "سرعة الإيقاع"}, {"en": "Dynamics", "ar": "شدة الصوت"}, {"en": "Texture", "ar": "نسيج موسيقي"}, {"en": "Harmony", "ar": "انسجام"}, {"en": "Instrument", "ar": "آلة موسيقية"}, {"en": "Composition", "ar": "تأليف موسيقي"}], "sourceNotes": [{"title": "Qualifications Scotland — Music", "url": "https://www.sqa.org.uk/sqa/45960.html"}, {"title": "Qualifications Scotland — National 5 Music", "url": "https://www.sqa.org.uk/sqa/45960.html"}, {"title": "Qualifications Scotland — Higher Music", "url": "https://www.sqa.org.uk/sqa/47895.html"}]}, "physical-education": {"id": "physical-education", "name": "Physical Education", "strapline": "Move with purpose. Understand performance.", "intro": "Explore the decisions, relationships and evidence behind performance. Suggested BGE themes are examples, not a prescribed school programme. Practical participation follows teacher guidance, inclusion arrangements and school safety procedures. Independent work here involves analysis and reflection, not unsupervised training plans, fitness testing or exercise regimes.", "bge": [{"title": "Team decisions", "question": "What makes a team effective?", "learn": ["Recognise space and support.", "Communicate constructively.", "Explain tactical choices."], "task": "Analyse a teacher-selected game clip and draw an alternative supporting position.", "extend": "Explain how the best decision changes when opponents change their formation."}, {"title": "Skills and feedback", "question": "How can feedback improve learning?", "learn": ["Identify a skill’s key features.", "Use focused observation.", "Set manageable process targets."], "task": "Use a supplied performance description to write one specific strength and a next learning step.", "extend": "Explain why several small changes at once might make progress hard to evaluate."}, {"title": "Performance factors", "question": "Why does performance vary?", "learn": ["Distinguish physical factors.", "Recognise mental and emotional factors.", "Identify social influences."], "task": "Analyse a fictional performer’s situation using at least two different factors and supporting evidence.", "extend": "Explain how factors can interact rather than operate independently."}, {"title": "Inclusive participation", "question": "How can sport welcome more people?", "learn": ["Recognise access barriers.", "Consider adaptations.", "Respect different needs."], "task": "Redesign the rules of a fictional school activity to improve participation while retaining its purpose.", "extend": "Explain how to gather participant feedback without making assumptions about ability."}], "senior": [{"level": "National 3 / National 4", "title": "Physical Education", "areas": ["Performance Skills", "Factors Impacting on Performance", "National 4 added-value performance"], "explain": "Develop practical performance and understanding of factors affecting it. National 4 includes added-value performance.", "assessment": "Internally assessed units and National 4 added value; pass/fail.", "source": {"title": "Qualifications Scotland — Physical Education", "url": "https://www.sqa.org.uk/sqa/45741.html"}}, {"level": "National 5", "title": "National 5 Physical Education", "areas": ["Performance skills", "Physical, mental, emotional and social factors", "Planning, monitoring and evaluating development"], "explain": "Use evidence to understand performance and develop skills in teacher-selected activities.", "assessment": "Performance and portfolio under current national requirements. Independent reflections are practice, not ready-made portfolio answers.", "source": {"title": "Qualifications Scotland — National 5 Physical Education", "url": "https://www.sqa.org.uk/sqa/45741.html"}}, {"level": "Higher", "title": "Higher Physical Education", "areas": ["Performance", "Factors impacting on performance", "Analysing and evaluating performance development"], "explain": "Connect data collection, approaches to development and evaluation with physical, mental, emotional and social factors.", "assessment": "Performance and question paper. Teachers confirm activities, adaptations and current assessment requirements.", "source": {"title": "Qualifications Scotland — Higher Physical Education", "url": "https://www.sqa.org.uk/sqa/47901.html"}}], "skills": [{"title": "Collect useful evidence", "explain": "An observation method must match the factor being investigated.", "try": "Design a paper checklist for decision-making in a teacher-selected clip.", "check": "Does it record a specific observable behaviour consistently?"}, {"title": "Explain performance factors", "explain": "Link a factor to an identifiable effect in context.", "try": "Explain how concentration could influence a passing decision.", "check": "Give a cause-and-effect chain rather than simply saying performance improves."}, {"title": "Set process targets", "explain": "Targets identify a controllable action and a way to review it.", "try": "Write a target for communication during teacher-led practice.", "check": "State what will be observed and when teacher feedback will be reviewed."}, {"title": "Evaluate fairly", "explain": "Use comparable evidence before judging an approach.", "try": "Compare two fictional observation records with different opponents.", "check": "Acknowledge contextual differences that limit the comparison."}], "practice": [{"question": "A player completes 18 of 24 passes. Calculate pass completion and identify a limitation of this measure.", "hint": "Convert the fraction to a percentage; consider difficulty.", "answer": "18/24 × 100 = 75%. The percentage does not show pass difficulty, pressure, distance or tactical value. Combine it with relevant observations.", "extend": "Explain why two players with 75% completion might contribute differently."}, {"question": "A performer loses concentration after making an error. Explain a possible effect and a suitable discussion point for the teacher.", "hint": "Connect attention to a specific next decision.", "answer": "Attention may remain on the mistake, delaying recognition of an available pass or defensive responsibility. Discuss a teacher-approved refocusing cue and how its effect could be observed.", "extend": "Distinguish concentration from a physical factor such as endurance."}, {"question": "A team wins after changing its tactics. Does this prove the new tactics caused improvement?", "hint": "Consider opposition and other contextual factors.", "answer": "No. Opposition, player availability, conditions and chance may also matter. Use repeated comparable observations and process evidence, not the result alone, to evaluate the change.", "extend": "Identify a measure that could show whether the tactical aim was achieved."}], "resources": [{"title": "sportscotland", "url": "https://sportscotland.org.uk/", "kind": "Read", "task": "Explore coaching or inclusion resources and identify an example of supportive practice."}, {"title": "Scottish Disability Sport", "url": "https://www.scottishdisabilitysport.com/", "kind": "Watch", "task": "Explore available sport resources and explain how an adaptation supports participation."}, {"title": "Youth Sport Trust", "url": "https://www.youthsporttrust.org/", "kind": "Read", "task": "Investigate leadership or inclusive participation and propose a school discussion question."}, {"title": "Olympic education", "url": "https://olympics.com/ioc/education", "kind": "Read", "task": "Evaluate a sporting-values example using a specific action and its impact."}, {"title": "Understanding Standards PE", "url": "https://www.understandingstandards.org.uk/Subjects/PhysicalEducation", "kind": "Read", "task": "Discuss published examples and assessment expectations with your teacher; some evidence is staff-only."}], "ipad": [{"title": "Tactical analyst", "steps": ["Use a teacher-approved game clip.", "Pause at three decision points and annotate space or positioning.", "Explain a possible choice and its consequence."], "evidence": "A reasoned analysis, with copyright and recording permission respected."}, {"title": "Feedback notebook", "steps": ["Record a teacher-agreed learning target.", "Add brief evidence after a supervised lesson.", "Review the target using one specific observation."], "evidence": "A personal learning reflection with no health or identity details shared publicly."}, {"title": "Inclusive design", "steps": ["Create a diagram of a fictional activity space.", "Annotate one rule, equipment or space adaptation.", "Explain how you would seek participant feedback."], "evidence": "An inclusion proposal ready for teacher discussion, not a home exercise task."}], "careers": [{"title": "Sports coaching", "linkToLearning": "Observation, communication and inclusive planning support participants.", "nextStep": "Explore college sports coaching and governing-body qualifications."}, {"title": "Physiotherapy", "linkToLearning": "Anatomy and movement analysis connect to further healthcare study.", "nextStep": "Check degree entry and professional registration requirements."}, {"title": "Leisure and recreation work", "linkToLearning": "Safety awareness and customer support help run facilities.", "nextStep": "Investigate leisure apprenticeships and local college pathways."}, {"title": "PE teaching or sports development", "linkToLearning": "Analysis, leadership and inclusive practice support learning and participation.", "nextStep": "Compare university teacher education and sports development routes."}], "parentTip": "Ask about a decision, teamwork moment or learning target rather than only a score. Encourage participation and teacher-guided progress without comparing bodies or prescribing extra training.", "vocabulary": [{"en": "Performance", "ar": "أداء"}, {"en": "Skill", "ar": "مهارة"}, {"en": "Team", "ar": "فريق"}, {"en": "Feedback", "ar": "تغذية راجعة"}, {"en": "Concentration", "ar": "تركيز"}, {"en": "Tactics", "ar": "تكتيكات"}, {"en": "Inclusion", "ar": "شمول"}, {"en": "Evaluation", "ar": "تقييم"}], "sourceNotes": [{"title": "Qualifications Scotland — Physical Education", "url": "https://www.sqa.org.uk/sqa/45741.html"}, {"title": "Qualifications Scotland — National 5 Physical Education", "url": "https://www.sqa.org.uk/sqa/45741.html"}, {"title": "Qualifications Scotland — Higher Physical Education", "url": "https://www.sqa.org.uk/sqa/47901.html"}]}}};
